var HISN_ITEMS = [{"c": 1, "ar": "أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ ﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالْأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾.", "n": 1, "a": "75", "ru": "Прибегаю к Аллаху от шайтана, побиваемого камнями. «Аллах — нет божества, кроме Него, Живого, Вседержителя. Не овладевают Им ни дремота, ни сон. Ему принадлежит то, что на небесах, и то, что на земле. Кто станет заступаться перед Ним иначе как с Его дозволения? Он знает то, что перед ними, и то, что позади них, а они не постигают из Его знания ничего, кроме того, что Он пожелает. Его Курси объемлет небеса и землю, и не тяготит Его оберегание их. Он — Возвышенный, Великий».", "kk": "Қуылған шайтаннан Аллаһқа сыйынамын. «Аллаһ — Одан басқа құдай жоқ, Ол — Тірі, Мәңгі Тұрушы. Оны мүлгу де, ұйқы да баспайды. Көктердегі нәрселер де, жердегі нәрселер де Онікі. Оның рұқсатынсыз Оның алдында кім шапағат ете алады? Ол олардың алдарындағыны да, арттарындағыны да біледі, ал олар Оның ілімінен Ол қалағанынан басқа ешнәрсені қамти алмайды. Оның Күрсісі көктер мен жерді қамтыған, оларды қорғау Оны шаршатпайды. Ол — Аса Жоғары, Аса Ұлы»."}, {"c": 1, "ar": "بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ* اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ (ثلاثَ مرَّاتٍ).", "n": 3, "a": "76", "ru": "С именем Аллаха, Милостивого, Милосердного. «Скажи: Он — Аллах Единый, Аллах Самодостаточный. Он не родил и не был рождён, и нет никого, равного Ему». С именем Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу рассвета от зла того, что Он сотворил, от зла мрака, когда он сгущается, от зла дующих на узлы и от зла завистника, когда он завидует». С именем Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу людей, Царю людей, Богу людей, от зла нашёптывающего искусителя, отступающего, который нашёптывает в груди людей, — из джиннов и людей». (три раза).", "kk": "Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: Ол — Аллаһ, Жалғыз. Аллаһ — Сәмад (ешкімге мұқтаж емес, бәрі Оған мұқтаж). Ол тумады әрі туылмады. Оған тең келетін ешкім жоқ». Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: Таң Раббысына сыйынамын — Ол жаратқан нәрселердің жамандығынан, қараңғылығы қоюланған кездегі түннің жамандығынан, түйіндерге үрлеушілердің жамандығынан және күндеген кездегі күншілдің жамандығынан». Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: адамдардың Раббысына, адамдардың Патшасына, адамдардың Құдайына сыйынамын — адамдардың көкіректеріне сыбырлайтын, сыбырлап алып, бой тасалайтын азғырушының жамандығынан, ол жындардан да, адамдардан да болады». (үш рет)."}, {"c": 1, "ar": "((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيرَ مَا بَعْدَهُ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي  هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ)). [ وإذا أمسى قال: أمسينا وأمسى الملك للَّه] [وإذا أمسى قال: رب أسألك خير ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة، وشر ما بعدها.]", "n": 1, "a": "77", "ru": "Мы дожили до утра, и утром власть принадлежит Аллаху, и хвала Аллаху. Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен. Господи, прошу Тебя о благе того, что в этом дне, и о благе того, что после него, и прибегаю к Тебе от зла того, что в этом дне, и от зла того, что после него. Господи, прибегаю к Тебе от лени и от дурной старости. Господи, прибегаю к Тебе от мучения в Огне и мучения в могиле. [А вечером говорит: «Мы дожили до вечера, и вечером власть принадлежит Аллаху».] [А вечером говорит: «Господи, прошу Тебя о благе того, что в этой ночи, и о благе того, что после неё, и прибегаю к Тебе от зла того, что в этой ночи, и от зла того, что после неё».]", "kk": "Біз таңға жеттік, билік те Аллаһқа тиесілі күйде таң атты, Аллаһқа мадақ. Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Онікі, мадақ Оған тән және Ол әр нәрсеге құдіретті. Раббым, Сенен осы күндегі нәрсенің жақсылығын және одан кейінгінің жақсылығын сұраймын, осы күндегі нәрсенің жамандығынан және одан кейінгінің жамандығынан Саған сыйынамын. Раббым, жалқаулықтан және кәріліктің жамандығынан Саған сыйынамын. Раббым, Тозақтағы азаптан және қабірдегі азаптан Саған сыйынамын. [Кешке қарай былай дейді: «Біз кешке жеттік, билік те Аллаһқа тиесілі күйде кеш кірді».] [Кешке қарай былай дейді: «Раббым, Сенен осы түндегі нәрсенің жақсылығын және одан кейінгінің жақсылығын сұраймын, осы түндегі нәрсенің жамандығынан және одан кейінгінің жамандығынан Саған сыйынамын».]"}, {"c": 1, "ar": "((اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا ، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ)). [وإذا أمسى قال: اللَّهم بك أمسينا، وبك أصبحنا، وبك نحيا، وبك نموت، وإليك المصير.]", "n": 1, "a": "78", "ru": "О Аллах, благодаря Тебе мы дожили до утра, благодаря Тебе дожили до вечера, благодаря Тебе живём, благодаря Тебе умираем, и к Тебе — воскрешение. [А вечером говорит: «О Аллах, благодаря Тебе мы дожили до вечера, благодаря Тебе дожили до утра, благодаря Тебе живём, благодаря Тебе умираем, и к Тебе — возвращение».]", "kk": "Уа, Аллаһ, Сенің құдіретіңмен таңға жеттік, Сенің құдіретіңмен кешке жеттік, Сенің құдіретіңмен өмір сүреміз, Сенің құдіретіңмен өлеміз және қайта тірілу Саған. [Кешке қарай былай дейді: «Уа, Аллаһ, Сенің құдіретіңмен кешке жеттік, Сенің құдіретіңмен таңға жеттік, Сенің құдіретіңмен өмір сүреміз, Сенің құдіретіңмен өлеміз және қайтар орын Саған».]"}, {"c": 1, "ar": "((اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ)).", "n": 1, "a": "79", "ru": "О Аллах, Ты — мой Господь, нет божества, кроме Тебя. Ты сотворил меня, и я — Твой раб, и я храню верность договору с Тобой и обещанию Тебе, насколько могу. Прибегаю к Тебе от зла того, что я совершил. Признаю перед Тобой Твою милость ко мне и признаю свой грех. Прости же меня, ведь никто не прощает грехов, кроме Тебя.", "kk": "Уа, Аллаһ, Сен менің Раббымсың, Сенен басқа құдай жоқ. Сен мені жараттың, мен Сенің құлыңмын. Шамам келгенше Сенімен жасаған антымда және Саған берген уәдемде тұрмын. Істеген ісімнің жамандығынан Саған сыйынамын. Маған берген нығметіңді Сенің алдыңда мойындаймын, күнәмді де мойындаймын. Мені кешіре гөр, өйткені күнәларды Сенен басқа ешкім кешірмейді."}, {"c": 1, "ar": "((اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ)) (أربعَ مَرَّاتٍ).[ وإذا أمسى قال: اللَّهم إني أمسيت...]", "n": 4, "a": "80", "ru": "О Аллах, поистине, я дожил до утра, призывая в свидетели Тебя, носителей Твоего Трона, Твоих ангелов и всё Твоё творение в том, что Ты — Аллах, нет божества, кроме Тебя, Единственного, у Которого нет сотоварища, и что Мухаммад — Твой раб и Твой посланник (четыре раза). [А вечером говорит: «О Аллах, поистине, я дожил до вечера…»]", "kk": "Уа, Аллаһ, мен таңға жетіп, Сені, Ғаршыңды көтерушілерді, періштелеріңді және бүкіл жаратылысыңды куә етемін: Сен — Аллаһсың, Сенен басқа құдай жоқ, Сен жалғызсың, Сенің серігің жоқ, ал Мұхаммед — Сенің құлың әрі елшің (төрт рет). [Кешке қарай былай дейді: «Уа, Аллаһ, мен кешке жетіп…»]"}, {"c": 1, "ar": "((اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ)). [وإذا أمسى قال: اللَّهم ما أمسى بي...]", "n": 1, "a": "81", "ru": "О Аллах, любая милость, что пришла утром ко мне или к кому-либо из Твоих творений, — от Тебя Одного, нет у Тебя сотоварища. Тебе хвала и Тебе благодарность. [А вечером говорит: «О Аллах, любая милость, что пришла вечером ко мне…»]", "kk": "Уа, Аллаһ, таңертең маған немесе жаратылысыңның біреуіне келген қандай да бір нығмет болса, ол тек Сенен ғана, Сенің серігің жоқ. Мадақ Саған, шүкір Саған. [Кешке қарай былай дейді: «Уа, Аллаһ, кешке маған келген…»]"}, {"c": 1, "ar": "((اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لاَ إِلَهَ إِلاَّ أَنْتَ. اللَّهُمَّ  إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ، وَالفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ، لاَ إِلَهَ إِلاَّ أَنْتَ)) (ثلاثَ مرَّاتٍ).", "n": 3, "a": "82", "ru": "О Аллах, даруй здоровье моему телу. О Аллах, даруй здоровье моему слуху. О Аллах, даруй здоровье моему зрению. Нет божества, кроме Тебя. О Аллах, поистине, я прибегаю к Тебе от неверия и бедности, и прибегаю к Тебе от мучения могилы. Нет божества, кроме Тебя (три раза).", "kk": "Уа, Аллаһ, тәніме саулық бер. Уа, Аллаһ, құлағыма саулық бер. Уа, Аллаһ, көзіме саулық бер. Сенен басқа құдай жоқ. Уа, Аллаһ, шын мәнінде, мен күпірліктен және кедейліктен Саған сыйынамын, қабір азабынан Саған сыйынамын. Сенен басқа құдай жоқ (үш рет)."}, {"c": 1, "ar": "((حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيهِ تَوَكَّلتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ)) (سَبْعَ مَرّاتٍ).", "n": 7, "a": "83", "ru": "Достаточно мне Аллаха, нет божества, кроме Него. На Него я уповаю, и Он — Господь великого Трона (семь раз).", "kk": "Маған Аллаһ жеткілікті, Одан басқа құдай жоқ. Оған тәуекел еттім, Ол — ұлы Ғаршының Раббысы (жеті рет)."}, {"c": 1, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَينِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي)).", "n": 1, "a": "84", "ru": "О Аллах, поистине, я прошу Тебя о прощении и благополучии в этом мире и в мире вечном. О Аллах, поистине, я прошу Тебя о прощении и благополучии в моей религии и в моей мирской жизни, в моей семье и в моём имуществе. О Аллах, скрой мои изъяны и избавь меня от того, что меня страшит. О Аллах, защити меня спереди и сзади, справа и слева и сверху, и прибегаю к Твоему величию от того, чтобы быть внезапно погубленным снизу.", "kk": "Уа, Аллаһ, шын мәнінде, мен Сенен дүние мен ақиретте кешірім және амандық сұраймын. Уа, Аллаһ, шын мәнінде, мен Сенен дінімде, дүниемде, отбасымда және мал-мүлкімде кешірім және амандық сұраймын. Уа, Аллаһ, айыптарымды жасыра гөр және қорқыныштарымнан аман ете гөр. Уа, Аллаһ, мені алдымнан, артымнан, оң жағымнан, сол жағымнан және үстімнен қорғай гөр. Астымнан кенеттен опат болудан Сенің ұлылығыңа сыйынамын."}, {"c": 1, "ar": "((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ وَشَرَكِهِ، وَأَنْ أَقْتَرِفَ عَلَى  نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).", "n": 1, "a": "85", "ru": "О Аллах, Знающий сокровенное и явное, Творец небес и земли, Господь и Владыка всякой вещи! Свидетельствую, что нет божества, кроме Тебя. Прибегаю к Тебе от зла моей души, от зла шайтана и его сетей, и от того, чтобы причинить зло самому себе или навлечь его на мусульманина.", "kk": "Уа, Аллаһ, ғайыпты да, көрінетінді де Білуші, көктер мен жерді Жаратушы, әр нәрсенің Раббысы әрі Иесі! Сенен басқа құдай жоқ екеніне куәлік етемін. Нәпсімнің жамандығынан, шайтанның жамандығынан және оның тұзағынан, өзіме жамандық жасаудан немесе оны бір мұсылманға тигізуден Саған сыйынамын."}, {"c": 1, "ar": "((بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ)) (ثلاثَ مرَّاتٍ).", "n": 3, "a": "86", "ru": "С именем Аллаха, с Чьим именем ничто не причиняет вреда ни на земле, ни на небе, и Он — Слышащий, Знающий (три раза).", "kk": "Атымен бірге жерде де, көкте де ешнәрсе зиян тигізе алмайтын Аллаһтың атымен. Ол — бәрін Естуші, бәрін Білуші (үш рет)."}, {"c": 1, "ar": "((رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ صلى الله عليه وسلم نَبِيّاً)) (ثلاثَ مرَّاتٍ).", "n": 3, "a": "87", "ru": "Я доволен Аллахом как Господом, исламом как религией и Мухаммадом ﷺ как пророком (три раза).", "kk": "Аллаһқа — Раббы ретінде, Исламға — дін ретінде, Мұхаммедке ﷺ — пайғамбар ретінде разы болдым (үш рет)."}, {"c": 1, "ar": "((يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ)).", "n": 1, "a": "88", "ru": "О Живой, о Вседержитель! К Твоей милости взываю о помощи: исправь все мои дела и не оставляй меня на самого себя ни на мгновение ока.", "kk": "Уа, Тірі, уа, Мәңгі Тұрушы! Сенің рақымыңа жүгініп, жәрдем тілеймін: барлық ісімді түзей гөр және мені көзді ашып-жұмғандай сәтке де өз-өзіме тастап қойма."}, {"c": 1, "ar": "((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ:فَتْحَهُ، وَنَصْرَهُ، وَنورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ)). [وإذا أمسى قال: أمسينا وأمسى الملك للَّه ربّ العالمين اللَّهم إني أسألك خير هذه الليلة: فتحها، ونصرها، ونورها، وبركتها، وهداها، وأعوذ بك من شر ما فيها، وشر ما بعدها.]", "n": 1, "a": "89", "ru": "Мы дожили до утра, и утром власть принадлежит Аллаху, Господу миров. О Аллах, поистине, я прошу Тебя о благе этого дня: о его победе, его помощи, его свете, его благодати и его верном руководстве, и прибегаю к Тебе от зла того, что в нём, и от зла того, что после него. [А вечером говорит: «Мы дожили до вечера, и вечером власть принадлежит Аллаху, Господу миров. О Аллах, поистине, я прошу Тебя о благе этой ночи: о её победе, её помощи, её свете, её благодати и её верном руководстве, и прибегаю к Тебе от зла того, что в ней, и от зла того, что после неё».]", "kk": "Біз таңға жеттік, билік те әлемдердің Раббысы Аллаһқа тиесілі күйде таң атты. Уа, Аллаһ, шын мәнінде, мен Сенен осы күннің жақсылығын: оның жеңісін, жәрдемін, нұрын, берекесін және тура жолын сұраймын, ондағы нәрсенің жамандығынан және одан кейінгінің жамандығынан Саған сыйынамын. [Кешке қарай былай дейді: «Біз кешке жеттік, билік те әлемдердің Раббысы Аллаһқа тиесілі күйде кеш кірді. Уа, Аллаһ, шын мәнінде, мен Сенен осы түннің жақсылығын: оның жеңісін, жәрдемін, нұрын, берекесін және тура жолын сұраймын, ондағы нәрсенің жамандығынан және одан кейінгінің жамандығынан Саған сыйынамын».]"}, {"c": 1, "ar": "((أَصْبَحْنا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صلى الله عليه وسلم، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشرِكِينَ)). [وإذا أمسى قال: أمسينا على فطرة الإسلام...]", "n": 1, "a": "90", "ru": "Мы дожили до утра на естестве ислама, на слове искренности, на религии нашего Пророка Мухаммада ﷺ и на вере нашего отца Ибрахима, который был единобожником, мусульманином, и не был из многобожников. [А вечером говорит: «Мы дожили до вечера на естестве ислама…»]", "kk": "Біз Ислам фитратында, ықылас сөзінде, Пайғамбарымыз Мұхаммедтің ﷺ дінінде және әкеміз Ибраһимнің ұстанымында таңға жеттік. Ол таухидке бет бұрған мұсылман еді әрі мүшріктерден болмаған еді. [Кешке қарай былай дейді: «Біз Ислам фитратында кешке жеттік…»]"}, {"c": 1, "ar": "((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ)) (مائة مرَّةٍ).", "n": 100, "a": "91", "ru": "Слава Аллаху и хвала Ему (сто раз).", "kk": "Аллаһ пәк және Оған мадақ (жүз рет)."}, {"c": 1, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) (عشرَ مرَّات) ، أَوْ (مرَّةً واحدةً عندَ الكَسَلِ).", "n": 10, "a": "92", "ru": "Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен. (десять раз) или (один раз, когда одолевает лень).", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Онікі, мадақ Оған тән және Ол әр нәрсеге құдіретті. (он рет) немесе (жалқаулық басқанда бір рет)."}, {"c": 1, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) (مائةَ مرَّةٍ إذا أصبحَ).", "n": 100, "a": "93", "ru": "Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен. (сто раз, когда наступит утро).", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Онікі, мадақ Оған тән және Ол әр нәрсеге құдіретті. (таң атқанда жүз рет)."}, {"c": 1, "ar": "((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ)) (ثلاثَ مرَّاتٍ إذا أصبحَ).", "n": 3, "a": "94", "ru": "Слава Аллаху и хвала Ему — числом Его творений, сколько Ему Самому угодно, весом Его Трона и количеством чернил для Его слов (три раза, когда наступит утро).", "kk": "Аллаһ пәк және Оған мадақ — жаратылыстарының санындай, Өзі разы болатындай, Ғаршының салмағындай және сөздерінің сиясындай (таң атқанда үш рет)."}, {"c": 1, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) (إذا أصبحَ).", "n": 1, "a": "95", "ru": "О Аллах, поистине, я прошу Тебя о полезном знании, благом уделе и принятом деянии (когда наступит утро).", "kk": "Уа, Аллаһ, шын мәнінде, мен Сенен пайдалы ілім, адал ризық және қабыл болған амал сұраймын (таң атқанда)."}, {"c": 1, "ar": "((أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ)) (مِائَةَ مَرَّةٍ فِي الْيَوْمِ).", "n": 100, "a": "96", "ru": "Прошу прощения у Аллаха и каюсь перед Ним (сто раз в день).", "kk": "Аллаһтан кешірім сұраймын және Оған тәубе етемін (күніне жүз рет)."}, {"c": 1, "ar": "((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) (ثلاثَ مرَّاتٍ إذا أمسى).", "n": 3, "a": "97", "ru": "Прибегаю к совершенным словам Аллаха от зла того, что Он сотворил (три раза, когда наступит вечер).", "kk": "Аллаһтың кемел сөздеріне Ол жаратқан нәрселердің жамандығынан сыйынамын (кеш кіргенде үш рет)."}, {"c": 1, "ar": "((اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبَيِّنَا مُحَمَّدٍ)) (عشرَ مرَّاتٍ).", "n": 10, "a": "98", "ru": "О Аллах, благослови и приветствуй нашего Пророка Мухаммада (десять раз).", "kk": "Уа, Аллаһ, Пайғамбарымыз Мұхаммедке салауат пен сәлем жолдай гөр (он рет)."}, {"c": 2, "ar": "((يَجْمَعُ كَفَّيْهِ ثُمَّ يَنْفُثُ فِيهِمَا فَيَقْرَأُ فِيهِمَا:بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقبَلَ مِنْ جَسَدِهِ)) (يفعلُ ذلك ثلاثَ مرَّاتٍ).", "n": 3, "a": "99", "ru": "Он складывает ладони вместе, затем дует в них и читает над ними: С именем Аллаха, Милостивого, Милосердного. «Скажи: Он — Аллах Единый, Аллах Самодостаточный. Он не родил и не был рождён, и нет никого, равного Ему». С именем Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу рассвета от зла того, что Он сотворил, от зла мрака, когда он сгущается, от зла дующих на узлы и от зла завистника, когда он завидует». С именем Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу людей, Царю людей, Богу людей, от зла нашёптывающего искусителя, отступающего, который нашёптывает в груди людей, — из джиннов и людей». Затем обтирает ими всё, что может, на своём теле, начиная с головы, лица и передней части тела (делает это три раза).", "kk": "Алақандарын біріктіреді де, оларға үрлеп, оларға мыналарды оқиды: Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: Ол — Аллаһ, Жалғыз. Аллаһ — Сәмад (ешкімге мұқтаж емес, бәрі Оған мұқтаж). Ол тумады әрі туылмады. Оған тең келетін ешкім жоқ». Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: Таң Раббысына сыйынамын — Ол жаратқан нәрселердің жамандығынан, қараңғылығы қоюланған кездегі түннің жамандығынан, түйіндерге үрлеушілердің жамандығынан және күндеген кездегі күншілдің жамандығынан». Аса Қамқор, Ерекше Мейірімді Аллаһтың атымен. «Айт: адамдардың Раббысына, адамдардың Патшасына, адамдардың Құдайына сыйынамын — адамдардың көкіректеріне сыбырлайтын, сыбырлап алып, бой тасалайтын азғырушының жамандығынан, ол жындардан да, адамдардан да болады». Содан кейін оларды денесінің қолы жеткен жерлеріне сипайды, басынан, бетінен және денесінің алдыңғы жағынан бастайды (мұны үш рет жасайды)."}, {"c": 2, "ar": "﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْـــــــــــدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾.", "n": 1, "a": "100", "ru": "«Аллах — нет божества, кроме Него, Живого, Вседержителя. Не овладевают Им ни дремота, ни сон. Ему принадлежит то, что на небесах, и то, что на земле. Кто станет заступаться перед Ним иначе как с Его дозволения? Он знает то, что перед ними, и то, что позади них, а они не постигают из Его знания ничего, кроме того, что Он пожелает. Его Курси объемлет небеса и землю, и не тяготит Его оберегание их. Он — Возвышенный, Великий».", "kk": "«Аллаһ — Одан басқа құдай жоқ, Ол — Тірі, Мәңгі Тұрушы. Оны мүлгу де, ұйқы да баспайды. Көктердегі нәрселер де, жердегі нәрселер де Онікі. Оның рұқсатынсыз Оның алдында кім шапағат ете алады? Ол олардың алдарындағыны да, арттарындағыны да біледі, ал олар Оның ілімінен Ол қалағанынан басқа ешнәрсені қамти алмайды. Оның Күрсісі көктер мен жерді қамтыған, оларды қорғау Оны шаршатпайды. Ол — Аса Жоғары, Аса Ұлы»."}, {"c": 2, "ar": "﴿آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ* لاَ يُكَلِّفُ اللَّهُ نَفْساً إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْراً كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآ أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾.", "n": 1, "a": "101", "ru": "«Посланник уверовал в то, что ниспослано ему от его Господа, и верующие тоже. Все они уверовали в Аллаха, Его ангелов, Его Писания и Его посланников: „Мы не делаем различия ни между кем из Его посланников“. И они сказали: „Мы услышали и повинуемся! Просим Твоего прощения, Господь наш, и к Тебе — возвращение“. Аллах не возлагает на душу ничего сверх её возможностей. Ей — то, что она приобрела, и против неё — то, что она приобрела. „Господь наш! Не взыскивай с нас, если мы забыли или ошиблись. Господь наш! Не возлагай на нас бремени, как Ты возложил его на тех, кто был до нас. Господь наш! Не обременяй нас тем, что нам не под силу. Извини нас, прости нас и помилуй нас! Ты — наш Покровитель, помоги же нам против людей неверующих“».", "kk": "«Елші өзіне Раббысынан түсірілгенге иман келтірді, мүміндер де. Олардың әрқайсысы Аллаһқа, Оның періштелеріне, кітаптарына және елшілеріне иман келтірді: „Біз Оның елшілерінің ешқайсысын бір-бірінен ажыратпаймыз“. Және олар: „Естідік және бойұсындық. Раббымыз, кешіруіңді тілейміз, қайтар орын Саған“, – деді. Аллаһ ешкімге шамасы келмейтін нәрсені жүктемейді. Әркімнің тапқан жақсылығы өзіне, жасаған жамандығы да өзіне. „Раббымыз, егер ұмытсақ немесе қателессек, бізді жазалама. Раббымыз, бізден бұрынғыларға жүктегеніңдей, бізге ауыр жүк жүктеме. Раббымыз, бізге шамамыз келмейтін нәрсені арқалатпа. Бізді кешір, бізді жарылқа және бізге рақым ет. Сен біздің Иемізсің, кәпір қауымға қарсы бізге жәрдем бер“»."}, {"c": 2, "ar": "((بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ)).", "n": 1, "a": "102", "ru": "С Твоим именем, Господь мой, я положил свой бок и с Тобой подниму его. Если Ты удержишь мою душу, то помилуй её, а если отпустишь её, то защити её тем, чем Ты защищаешь Своих праведных рабов.", "kk": "Раббым, Сенің атыңмен қырыма жаттым және Сенің арқаңда оны көтеремін. Егер жанымды ұстап қалсаң, оған рақым ет, ал егер оны қайтарсаң, ізгі құлдарыңды немен қорғасаң, оны да сонымен қорға."}, {"c": 2, "ar": "((اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْياهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ)).", "n": 1, "a": "103", "ru": "О Аллах, поистине, Ты сотворил мою душу и Ты упокоишь её. Тебе принадлежат её смерть и её жизнь. Если Ты оживишь её — защити её, а если умертвишь её — прости её. О Аллах, поистине, я прошу Тебя о благополучии.", "kk": "Уа, Аллаһ, шын мәнінде, жанымды Сен жараттың және оны Сен аласың. Оның өлімі де, өмірі де Сенікі. Егер оны тірі қалдырсаң, оны қорға, ал егер оны өлтірсең, оны кешір. Уа, Аллаһ, шын мәнінде, мен Сенен амандық сұраймын."}, {"c": 2, "ar": "((اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ)).", "n": 1, "a": "104", "ru": "О Аллах, защити меня от Твоего наказания в тот день, когда Ты воскресишь Своих рабов.", "kk": "Уа, Аллаһ, құлдарыңды қайта тірілтетін күні мені азабыңнан сақта."}, {"c": 2, "ar": "((بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا)).", "n": 1, "a": "105", "ru": "С Твоим именем, о Аллах, я умираю и оживаю.", "kk": "Уа, Аллаһ, Сенің атыңмен өлемін және тірілемін."}, {"c": 2, "ar": "((سُبْحَانَ اللَّهِ (ثلاثاً وثلاثين) وَالْحَمْدُ لِلَّهِ (ثلاثاً وثلاثين) وَاللَّهُ أَكْبَرُ (أربعاً وثلاثينَ))).", "n": 33, "a": "106", "ru": "Слава Аллаху (тридцать три раза), хвала Аллаху (тридцать три раза) и Аллах Велик (тридцать четыре раза).", "kk": "Аллаһ пәк (отыз үш рет), Аллаһқа мадақ (отыз үш рет) және Аллаһ ұлы (отыз төрт рет)."}, {"c": 2, "ar": "((اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ)).", "n": 1, "a": "107", "ru": "О Аллах, Господь семи небес и Господь земли, Господь великого Трона, наш Господь и Господь всякой вещи, Раскалывающий зерно и косточку, Ниспославший Таурат, Инджиль и Фуркан! Прибегаю к Тебе от зла всякой вещи, которую Ты держишь за хохол. О Аллах, Ты — Первый, и нет ничего прежде Тебя; Ты — Последний, и нет ничего после Тебя; Ты — Явный, и нет ничего над Тобой; Ты — Скрытый, и нет ничего ближе Тебя. Погаси за нас долг и избавь нас от бедности.", "kk": "Уа, Аллаһ, жеті көктің Раббысы, жердің Раббысы, ұлы Ғаршының Раббысы, біздің Раббымыз әрі әр нәрсенің Раббысы, дән мен сүйекті жарушы, Тәурат, Інжіл және Фұрқанды түсіруші! Сен маңдайынан ұстап тұрған әр нәрсенің жамандығынан Саған сыйынамын. Уа, Аллаһ, Сен — Әуелсің, Сенен бұрын ешнәрсе жоқ; Сен — Ақырсың, Сенен кейін ешнәрсе жоқ; Сен — Заһирсің, Сенің үстіңде ешнәрсе жоқ; Сен — Батинсің, Сенен жақын ешнәрсе жоқ. Қарызымызды өтей гөр және бізді кедейліктен құтқарып, бай ете гөр."}, {"c": 2, "ar": "((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ)).", "n": 1, "a": "108", "ru": "Хвала Аллаху, Который накормил нас и напоил, избавил нас от нужды и дал нам приют. Сколько же тех, у кого нет ни того, кто избавил бы их от нужды, ни того, кто дал бы им приют!", "kk": "Бізді тамақтандырып, сусындатқан, бізге жеткілікті етіп, бізге баспана берген Аллаһқа мадақ. Қаншама адамның мұқтаждығын өтеуші де, баспана беруші де жоқ!"}, {"c": 2, "ar": "((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).", "n": 1, "a": "109", "ru": "О Аллах, Знающий сокровенное и явное, Творец небес и земли, Господь и Владыка всякой вещи! Свидетельствую, что нет божества, кроме Тебя. Прибегаю к Тебе от зла моей души, от зла шайтана и его многобожия, и от того, чтобы причинить зло самому себе или навлечь его на мусульманина.", "kk": "Уа, Аллаһ, ғайыпты да, көрінетінді де Білуші, көктер мен жерді Жаратушы, әр нәрсенің Раббысы әрі Иесі! Сенен басқа құдай жоқ екеніне куәлік етемін. Нәпсімнің жамандығынан, шайтанның жамандығынан және оның ширкінен, өзіме жамандық жасаудан немесе оны бір мұсылманға тигізуден Саған сыйынамын."}, {"c": 2, "ar": "((يَقْرَأُ ﴿الم﴾ تَنْزِيلَ السَّجْدَة ِ،  وَتَبَارَكَ الَّذي بِيَدِهِ الْمُلْكُ)).", "n": 1, "a": "110", "ru": "Он читает «Алиф. Лям. Мим.» — «Ниспослание…» (сура ас-Сажда) и «Благословен Тот, в Чьей руке власть» (сура аль-Мульк).", "kk": "«Әлиф. Ләм. Мим.» — «Түсірілуі…» (әс-Сәжде сүресі) және «Билік қолында болған Ол қандай берекелі» (әл-Мүлк сүресі) сүрелерін оқиды."}, {"c": 2, "ar": "((اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)).", "n": 1, "a": "111", "ru": "О Аллах, я предал свою душу Тебе, вверил своё дело Тебе, обратил своё лицо к Тебе и прислонил свою спину к Тебе, с желанием Тебя и страхом перед Тобой. Нет ни убежища, ни спасения от Тебя, кроме как у Тебя. Я уверовал в Твоё Писание, которое Ты ниспослал, и в Твоего Пророка, которого Ты отправил.", "kk": "Уа, Аллаһ, жанымды Саған тапсырдым, ісімді Саған жүктедім, жүзімді Саған бұрдым, арқамды Саған сүйедім — Саған үміт артып әрі Сенен қорқып. Сенен қашып баратын пана да, құтылар жер де жоқ, тек Саған ғана. Сен түсірген Кітабыңа және Сен жіберген Пайғамбарыңа иман келтірдім."}, {"c": 3, "ar": "( الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ )", "n": 1, "a": "1", "ru": "Хвала Аллаху, Который оживил нас после того, как умертвил нас, и к Нему — воскрешение.", "kk": "Бізді өлтіргеннен кейін тірілткен Аллаһқа мадақ, қайта тірілу де Оған."}, {"c": 3, "ar": "( لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَريكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ للَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفرْ لِي ).", "n": 1, "a": "2", "ru": "Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен. Слава Аллаху, хвала Аллаху, нет божества, кроме Аллаха, Аллах Велик, и нет мощи и силы ни у кого, кроме Аллаха, Высокого, Великого. Господи, прости меня.", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Онікі, мадақ Оған тән және Ол әр нәрсеге құдіретті. Аллаһ пәк, Аллаһқа мадақ, Аллаһтан басқа құдай жоқ, Аллаһ ұлы, Аса Жоғары, Аса Ұлы Аллаһтан басқа ешбір күш те, қуат та жоқ. Раббым, мені кешір."}, {"c": 3, "ar": "( الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لي بِذِكْرِهِ )", "n": 1, "a": "3", "ru": "Хвала Аллаху, Который даровал здоровье моему телу, вернул мне мою душу и позволил мне поминать Его.", "kk": "Тәніме саулық берген, жанымды маған қайтарған және Өзін еске алуыма рұқсат еткен Аллаһқа мадақ."}, {"c": 3, "ar": "﴿ إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لأُوْلِي الألْبَابِ * الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَاماً وَقُعُوداً وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ* رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ* رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلإِيمَانِ أَنْ آمِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ* رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ* فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَاباً مِّن عِندِ اللَّهِ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ * لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ * مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ * لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللَّهِ وَمَا عِندَ اللَّهِ خَيْرٌ لِّلأَبْرَارِ * وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لاَ يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَناً قَلِيلاً أُوْلَئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ*يَا أَيُّهَا الَّذِينَ آمَنُواْ اصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ ﴾", "n": 1, "a": "4", "ru": "«Поистине, в сотворении небес и земли и в смене ночи и дня — знамения для обладающих разумом, которые поминают Аллаха стоя, сидя и лёжа на боку и размышляют о сотворении небес и земли: „Господь наш! Ты не сотворил это напрасно. Пречист Ты! Защити же нас от мучений Огня. Господь наш! Поистине, кого Ты введёшь в Огонь, того Ты опозорил, и у беззаконников не будет помощников. Господь наш! Поистине, мы услышали глашатая, который призывал к вере: уверуйте в вашего Господа, — и мы уверовали. Господь наш! Прости же нам наши грехи, загладь наши дурные деяния и упокой нас вместе с благочестивыми. Господь наш! Даруй нам то, что Ты обещал нам через Твоих посланников, и не позорь нас в День воскресения. Поистине, Ты не нарушаешь обещания“. И ответил им их Господь: „Я не дам пропасть деянию ни одного из вас, будь то мужчина или женщина, — вы одни от других. Тем, которые переселились, были изгнаны из своих жилищ, претерпели обиды на Моём пути, сражались и были убиты, Я непременно заглажу их дурные деяния и непременно введу их в сады, под которыми текут реки, в награду от Аллаха“. А у Аллаха — прекрасная награда. Пусть не обольщает тебя то, как неверующие разъезжают по странам. Это — малое наслаждение, а затем их пристанищем будет Геенна. И как же скверно это ложе! Но тем, которые боялись своего Господа, — сады, под которыми текут реки, где они пребудут вечно, как угощение от Аллаха. А то, что у Аллаха, лучше для благочестивых. Поистине, среди людей Писания есть такие, которые веруют в Аллаха, и в то, что ниспослано вам, и в то, что ниспослано им, смиряясь перед Аллахом, и не продают знамения Аллаха за ничтожную цену. Им — их награда у их Господа. Поистине, Аллах скор в расчёте. О те, которые уверовали! Будьте терпеливы, превосходите других в терпении, стойко держитесь на рубежах и бойтесь Аллаха, — быть может, вы преуспеете».", "kk": "«Шын мәнінде, көктер мен жердің жаратылуында және түн мен күндіздің алмасуында ақыл иелері үшін белгілер бар. Олар Аллаһты тұрғанда да, отырғанда да, қырынан жатқанда да еске алады және көктер мен жердің жаратылуы жайлы ойланады: „Раббымыз, Сен мұны бекер жаратпадың. Сен пәксің! Бізді Тозақ азабынан сақта. Раббымыз, шын мәнінде, Сен кімді Тозаққа кіргізсең, оны масқара еттің. Залымдардың ешбір жәрдемшісі жоқ. Раббымыз, шын мәнінде, біз: Раббыларыңа иман келтіріңдер, – деп иманға шақырған жаршыны естідік те, иман келтірдік. Раббымыз, күнәларымызды кешір, жамандықтарымызды өшір және бізді ізгілермен бірге жанымызды ал. Раббымыз, елшілерің арқылы бізге уәде еткеніңді бер және Қиямет күні бізді масқара етпе. Шын мәнінде, Сен уәдеңнен таймайсың“. Раббылары оларға: „Мен сендерден ер болсын, әйел болсын, ешбір амал етушінің амалын зая етпеймін, сендер бір-біріңненсіңдер. Хижрет еткендердің, жұрттарынан қуылғандардың, Менің жолымда жапа шеккендердің, соғысып, өлтірілгендердің жамандықтарын міндетті түрде өшіремін және оларды астынан өзендер ағып жатқан бақтарға міндетті түрде кіргіземін. Бұл — Аллаһ тарапынан берілетін сый“, – деп жауап берді. Ең көркем сый Аллаһтың құзырында. Кәпірлердің елдерді аралап жүруі сені алдамасын. Бұл — аз ғана пайдалану, содан кейін олардың баратын жері — Жаһаннам. Ол нендей жаман төсек! Ал Раббыларынан қорыққандар үшін астынан өзендер ағып жатқан бақтар бар, олар онда мәңгі қалады. Бұл — Аллаһ тарапынан дайындалған қонақасы. Аллаһтың құзырындағы нәрсе ізгілер үшін жақсырақ. Шын мәнінде, Кітап иелерінің арасында Аллаһқа, сендерге түсірілгенге және өздеріне түсірілгенге иман келтіретін, Аллаһқа бойұсынатын, Аллаһтың аяттарын болмашы бағаға сатпайтындар бар. Солардың сыйы Раббыларының құзырында. Шын мәнінде, Аллаһ есеп алуда өте жылдам. Әй, иман келтіргендер! Сабыр етіңдер, сабырда озыңдар, шептерде берік тұрыңдар және Аллаһтан қорқыңдар, сонда мүмкін, құтылып, табысқа жетерсіңдер»."}, {"c": 4, "ar": "([بِسْمِ اللَّهِ] اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبائِث).", "n": 1, "a": "10", "ru": "([С именем Аллаха.] О Аллах, поистине, я прибегаю к Тебе от скверных существ мужского и женского пола).", "kk": "([Аллаһтың атымен.] Уа, Аллаһ, шын мәнінде, мен еркек және ұрғашы лас жын-шайтандардан Саған сыйынамын)."}, {"c": 5, "ar": "(غُفْرَانَكَ).", "n": 1, "a": "11", "ru": "(Прошу Твоего прощения).", "kk": "(Кешіруіңді сұраймын)."}, {"c": 6, "ar": "(بِسْمِ اللَّهِ).", "n": 1, "a": "12", "ru": "(С именем Аллаха).", "kk": "(Аллаһтың атымен)."}, {"c": 7, "ar": "(أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ..).", "n": 1, "a": "13", "ru": "«Свидетельствую, что нет божества, кроме Аллаха, Единого, у Которого нет сотоварища, и свидетельствую, что Мухаммад — Его раб и Посланник…»", "kk": "«Аллаһтан басқа құдай жоқ екеніне, Оның жалғыз екеніне әрі серігі жоқ екеніне куәлік беремін және Мұхаммед Оның құлы әрі елшісі екеніне куәлік беремін…»"}, {"c": 7, "ar": "(اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ)", "n": 1, "a": "14", "ru": "«О Аллах, сделай меня одним из кающихся и сделай меня одним из очищающихся».", "kk": "«Уа, Аллаһ, мені тәубе етушілерден қыл және мені тазаланушылардан қыл»."}, {"c": 7, "ar": "(سُبْحانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ).", "n": 1, "a": "15", "ru": "«Пречист Ты, о Аллах, и хвала Тебе! Свидетельствую, что нет божества, кроме Тебя. Прошу у Тебя прощения и каюсь перед Тобой».", "kk": "«Уа, Аллаһ, Сен пәксің және Саған мадақ! Сенен басқа құдай жоқ екеніне куәлік беремін. Сенен кешірім сұраймын және Саған тәубе етемін»."}, {"c": 8, "ar": "(بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَاَ حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ).", "n": 1, "a": "16", "ru": "«С именем Аллаха, уповаю на Аллаха, и нет мощи и нет силы, кроме как у Аллаха».", "kk": "«Аллаһтың атымен, Аллаһқа тәуекел еттім, күш те, қуат та тек Аллаһ арқылы»."}, {"c": 8, "ar": "(اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ).", "n": 1, "a": "17", "ru": "«О Аллах, поистине, я прибегаю к Тебе от того, чтобы сбиться с пути или быть сбитым с пути, оступиться или быть приведённым к оступлению, поступить несправедливо или подвергнуться несправедливости, поступить невежественно или чтобы со мной поступили невежественно».", "kk": "«Уа, Аллаһ, адасудан немесе адастырылудан, тайып кетуден немесе тайдырылудан, зұлымдық жасаудан немесе зұлымдыққа ұшыраудан, надандық жасаудан немесе маған қатысты надандық жасалуынан Саған сыйынамын»."}, {"c": 9, "ar": "(بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا، ثُمَّ لِيُسَلِّمْ عَلَى أَهْلِهِ).", "n": 1, "a": "18", "ru": "«С именем Аллаха мы вошли, с именем Аллаха мы вышли, и на Аллаха, нашего Господа, мы уповаем». Затем пусть поприветствует свою семью.", "kk": "«Аллаһтың атымен кірдік, Аллаһтың атымен шықтық және Раббымыз Аллаһқа тәуекел еттік». Содан кейін отбасына сәлем берсін."}, {"c": 10, "ar": "(اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً، وَفِي لِسَانِي نُوراً، وَفِي سَمْعِي نُوراً، وَفِي بَصَرِي نُوراً، وَمِنْ فَوْقِي نُوراً، وَمِنْ تَحْتِي نُوراً، وَعَنْ يَمِينِي نُوراً، وَعَنْ شِمَالِي نُوراً، وَمِنْ أَمَامِي نُوراً، وَمِنْ خَلْفِي نُوراً، وَاجْعَلْ فِي نَفْسِي نُوراً، وَأَعْظِمْ لِي نُوراً، وَعَظِّم لِي نُوراً، وَاجْعَلْ لِي نُوراً، وَاجْعَلْنِي نُوراً، اللَّهُمَّ أَعْطِنِي نُوراً، وَاجْعَلْ فِي عَصَبِي نُوراً، وَفِي لَحْمِي نُوراً، وَفِي دَمِي نُوراً، وَفِي شَعْرِي نُوراً، وَفِي بَشَرِي نُوراً)([اللَّهُمَّ اجْعَلْ لِي نُوراً فِي قَبْرِي... وَنُوراً فِي عِظَامِي])[(وَزِدْنِي نُوراً، وَزِدْنِي نُوراً، وَزِدْنِي نُوراً)][(وَهَبْ لِي نُوراً عَلَى نُورٍ)]", "n": 1, "a": "19", "ru": "«О Аллах, помести свет в моё сердце, свет — в мой язык, свет — в мой слух, свет — в моё зрение, свет — надо мной, свет — подо мной, свет — справа от меня, свет — слева от меня, свет — впереди меня, свет — позади меня; помести свет в мою душу, сделай для меня свет обильным, сделай для меня свет великим, даруй мне свет и сделай меня светом. О Аллах, дай мне свет, помести свет в мои сухожилия, свет — в мою плоть, свет — в мою кровь, свет — в мои волосы и свет — в мою кожу». [«О Аллах, даруй мне свет в моей могиле… и свет в моих костях»]. [«И прибавь мне света, и прибавь мне света, и прибавь мне света»]. [«И даруй мне свет поверх света»].", "kk": "«Уа, Аллаһ, жүрегіме нұр, тіліме нұр, құлағыма нұр, көзіме нұр бер; үстімнен нұр, астымнан нұр, оң жағымнан нұр, сол жағымнан нұр, алдымнан нұр, артымнан нұр қыл; жаныма нұр бер, маған нұрды мол қыл, маған нұрды ұлық қыл, маған нұр бер және мені нұр қыл. Уа, Аллаһ, маған нұр бер; жүйкелеріме нұр, етіме нұр, қаныма нұр, шашыма нұр және теріме нұр бер». [«Уа, Аллаһ, қабірімде маған нұр бер… әрі сүйектерімде нұр бер»]. [«Маған нұрды арттыр, маған нұрды арттыр, маған нұрды арттыр»]. [«Маған нұр үстіне нұр сыйла»]."}, {"c": 11, "ar": "(يَبْدَأُ بِرِجْلِهِ الْيُمْنَى) ، وَيَقُولُ: ((أَعُوذُ بِاللَّهِ العَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ))  [بِسْمِ اللَّهِ، وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ]  ((اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ)).", "n": 1, "a": "20", "ru": "(Начинает с правой ноги) и говорит: «Прибегаю к Аллаху Великому, к Его благородному Лику и к Его извечной власти от шайтана, побиваемого камнями». [«С именем Аллаха, и благословение] [и мир Посланнику Аллаха»]. «О Аллах, открой мне врата Твоей милости».", "kk": "(Оң аяғымен бастайды) және былай дейді: «Ұлы Аллаһқа, Оның ардақты Жүзіне және Оның ежелден бар билігіне сүйеніп, қуылған шайтаннан пана сұраймын». [«Аллаһтың атымен, салауат] [және сәлем Аллаһтың елшісіне болсын»]. «Уа, Аллаһ, маған рақымыңның есіктерін аш»."}, {"c": 12, "ar": "((يَبْدَأُ بِرِجْلِهِ الْيُسْرَى))  وَيَقُولُ: ((بِسْمِ اللَّهِ وَالصّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِك، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ)).", "n": 1, "a": "21", "ru": "(Начинает с левой ноги) и говорит: «С именем Аллаха, благословение и мир Посланнику Аллаха. О Аллах, поистине, я прошу Тебя о Твоей щедрости. О Аллах, защити меня от шайтана, побиваемого камнями».", "kk": "(Сол аяғымен бастайды) және былай дейді: «Аллаһтың атымен, Аллаһтың елшісіне салауат пен сәлем болсын. Уа, Аллаһ, Сенен кеңшілігіңді (пазылыңды) сұраймын. Уа, Аллаһ, мені қуылған шайтаннан қорға»."}, {"c": 13, "ar": "يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي ((حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ)) فَيقُولُ: ((لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "n": 1, "a": "22", "ru": "Повторяет то же, что говорит муаззин, кроме слов «Спешите на молитву» и «Спешите к спасению» — при них он говорит: «Нет мощи и нет силы, кроме как у Аллаха».", "kk": "Мүәззиннің айтқанын қайталап айтады, тек «Намазға келіңдер» және «Құтылуға келіңдер» деген сөздерде: «Күш те, қуат та тек Аллаһ арқылы», – дейді."}, {"c": 13, "ar": "يَقُولُ: ((وَأَنَا أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبَّاً، وَبِمُحَمَّدٍ رَسُولاً، وَبِالْإِسْلاَمِ دِينَاً)) ((يَقُولُ ذَلِكَ عَقِبَ تَشَهُّدِ الْمُؤَذِّنِ)).", "n": 1, "a": "23", "ru": "Говорит: «И я свидетельствую, что нет божества, кроме Аллаха, Единого, у Которого нет сотоварища, и что Мухаммад — Его раб и Посланник. Я доволен Аллахом как Господом, Мухаммадом как Посланником и Исламом как религией». (Говорит это сразу после того, как муаззин произнесёт свидетельство.)", "kk": "Былай дейді: «Мен де Аллаһтан басқа құдай жоқ екеніне, Оның жалғыз екеніне әрі серігі жоқ екеніне және Мұхаммед Оның құлы әрі елшісі екеніне куәлік беремін. Аллаһқа – Раббы ретінде, Мұхаммедке – елші ретінде, Исламға – дін ретінде разы болдым». (Мұны мүәззин шаһадат айтқаннан кейін бірден айтады.)"}, {"c": 13, "ar": "((يُصَلِّي عَلَى النَّبِيِّ صلى الله عليه وسلم بَعْدَ فَرَاغِهِ مِنْ إِجَابَةِ الْمُؤَذِّنِ)).", "n": 1, "a": "24", "ru": "(Произносит благословение Пророку ﷺ после того, как закончит отвечать муаззину.)", "kk": "(Мүәззинге жауап беріп болғаннан кейін Пайғамбарға ﷺ салауат айтады.)"}, {"c": 13, "ar": "يَقُولُ: ((اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّداً الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامَاً مَحمُوداً الَّذِي وَعَدْتَهُ، [إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ])).", "n": 1, "a": "25", "ru": "Говорит: «О Аллах, Господь этого совершенного призыва и устанавливаемой молитвы! Даруй Мухаммаду аль-Василю и превосходство и воздвигни его на достохвальное место, которое Ты ему обещал, [ведь, поистине, Ты не нарушаешь обещания]».", "kk": "Былай дейді: «Уа, Аллаһ, осы кәміл шақырудың және орындалғалы тұрған намаздың Раббысы! Мұхаммедке уәсиланы және артықшылықты (пазиләтті) бер және оны Өзің уәде еткен мақталған мақамға жеткізіп тірілт, [шын мәнінде, Сен уәдеңді бұзбайсың]»."}, {"c": 13, "ar": "((يَدْعُو لِنَفسِهِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فَإِنَّ الدُّعَاءَ حِينَئِذٍ لاَ يُرَدُّ)).", "n": 1, "a": "26", "ru": "(Пусть молит Аллаха за себя между азаном и икаматом, ибо мольба в это время не отвергается.)", "kk": "(Азан мен қамат арасында өзі үшін дұға жасайды, өйткені бұл уақытта дұға қайтарылмайды.)"}, {"c": 14, "ar": "(الْحَمْدُ للَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّة...)", "n": 1, "a": "5", "ru": "«Хвала Аллаху, Который облачил меня в эту (одежду) и наделил меня ею без какой-либо мощи и силы с моей стороны…»", "kk": "«Маған осы (киімді) кигізген және оны менің ешқандай күш-қуатымсыз маған ризық етіп берген Аллаһқа мадақ…»"}, {"c": 15, "ar": "( اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ).", "n": 1, "a": "6", "ru": "«О Аллах, Тебе хвала! Ты облачил меня в неё. Прошу Тебя о благе её и благе того, для чего она сделана, и прибегаю к Тебе от зла её и зла того, для чего она сделана».", "kk": "«Уа, Аллаһ, Саған мадақ! Оны маған Сен кигіздің. Сенен оның жақсылығын және оның не үшін жасалғанының жақсылығын сұраймын, оның жамандығынан және оның не үшін жасалғанының жамандығынан Саған сыйынамын»."}, {"c": 16, "ar": "(تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى)", "n": 1, "a": "7", "ru": "«Изнашивай, а Аллах Всевышний даст замену».", "kk": "«Тоздыра бер, ал Аллаһ Тағала орнына басқасын береді»."}, {"c": 16, "ar": "(اِلْبَسْ جَدِيداً وَعِشْ حَمِيداً وَمُتْ شَهِيداً).", "n": 1, "a": "8", "ru": "«Носи новое, живи достойно и умри шахидом».", "kk": "«Жаңа ки, мақтаулы өмір сүр және шейіт болып дүниеден өт»."}, {"c": 17, "ar": "(بِسْمِ اللَّهِ).", "n": 1, "a": "9", "ru": "«С именем Аллаха».", "kk": "«Аллаһтың атымен»."}, {"c": 18, "ar": "((اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ، بِالثَّلْجِ وَالْماءِ وَالْبَرَدِ)).", "n": 1, "a": "27", "ru": "«О Аллах, отдали меня от моих прегрешений, как Ты отдалил друг от друга восток и запад. О Аллах, очисти меня от моих прегрешений, как очищается белая одежда от грязи. О Аллах, омой меня от моих прегрешений снегом, водой и градом».", "kk": "«Уа, Аллаһ, шығыс пен батыстың арасын қалай алыстатсаң, мен бен күнәларымның арасын да солай алыстат. Уа, Аллаһ, ақ киім кірден қалай тазартылса, мені де күнәларымнан солай тазарт. Уа, Аллаһ, мені күнәларымнан қармен, сумен және бұршақпен жуып тазарт»."}, {"c": 18, "ar": "((سُبْحانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلاَ إِلَهَ غَيْرُكَ)).", "n": 1, "a": "28", "ru": "«Пречист Ты, о Аллах, и хвала Тебе! Благословенно Твоё имя, превыше всего Твоё величие, и нет божества, кроме Тебя».", "kk": "«Уа, Аллаһ, Сен пәксің және Саған мадақ! Есімің берекелі, ұлылығың жоғары және Сенен басқа құдай жоқ»."}, {"c": 18, "ar": "((وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلاَتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لاَ يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لاَ يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالخَيْرُ كُلُّهُ بِيَـــــــدَيْكَ، وَالشَّـــــرُّ لَيْسَ إِلَيْــــــكَ، أَنَا بِكَ وَإِلَيْكَ، تَبارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ)).", "n": 1, "a": "29", "ru": "«Я обратил своё лицо к Тому, Кто сотворил небеса и землю, будучи ханифом, и я не из многобожников. Поистине, моя молитва, моё поклонение, моя жизнь и моя смерть — для Аллаха, Господа миров, у Которого нет сотоварища. Это мне велено, и я — из мусульман. О Аллах, Ты — Царь, нет божества, кроме Тебя. Ты — мой Господь, а я — Твой раб. Я поступил несправедливо по отношению к себе и признал свой грех, так прости же мне все мои грехи, ведь, поистине, никто не прощает грехи, кроме Тебя. Наставь меня на лучший нрав — никто не наставляет на лучший из него, кроме Тебя, — и отврати от меня дурной нрав — никто не отвратит от меня его дурное, кроме Тебя. Вот я перед Тобой, отвечаю на Твой зов и всегда готов служить Тебе! Всё благо — в Твоих руках, а зло к Тебе не относится. Я существую Тобой и стремлюсь к Тебе. Благословен Ты и Возвышен! Прошу у Тебя прощения и каюсь перед Тобой».", "kk": "«Жүзімді көктер мен жерді жаратқан Затқа ханиф ретінде бұрдым, мен мүшріктерден емеспін. Шын мәнінде, менің намазым, құрбандығым (ғибадатым), өмірім және өлімім – әлемдердің Раббысы Аллаһ үшін, Оның серігі жоқ. Маған осы бұйырылды және мен мұсылмандарданмын. Уа, Аллаһ, Сен – Патшасың, Сенен басқа құдай жоқ. Сен – менің Раббымсың, ал мен – Сенің құлыңмын. Мен өзіме зұлымдық жасадым және күнәмді мойындадым, ендеше менің барлық күнәларымды кешір, өйткені күнәларды Сенен басқа ешкім кешірмейді. Мені ең көркем мінезге бағытта, оның ең көркеміне Сенен басқа ешкім бағыттамайды. Менен жаман мінезді аулақ қыл, оның жаманын менен Сенен басқа ешкім аулақ қылмайды. Міне, мен шақыруыңа жауап беріп, Саған қызмет етуге әрдайым дайынмын! Барлық жақсылық Сенің қолыңда, ал жамандық Саған телінбейді. Мен Сен арқылы бармын және Саған бет бұрамын. Сен берекелісің және аса жоғарысың! Сенен кешірім сұраймын және Саған тәубе етемін»."}, {"c": 18, "ar": "((اللَّهُمَّ رَبَّ جِبْرَائِيلَ، وَمِيْكَائِيلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالأَرْضِ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ)).", "n": 1, "a": "30", "ru": "«О Аллах, Господь Джибриля, Микаиля и Исрафиля, Творец небес и земли, Знающий сокрытое и явное! Ты судишь между Своими рабами в том, в чём они расходились. Наставь меня с Твоего позволения на истину в том, в чём разошлись. Поистине, Ты наставляешь на прямой путь, кого пожелаешь».", "kk": "«Уа, Аллаһ, Жәбірейілдің, Микайылдың және Исрафилдің Раббысы, көктер мен жерді Жаратушы, ғайыпты да, көрінетінді де Білуші! Құлдарыңның арасында олар келіспей қалған нәрселер жайында Сен үкім етесің. Келіспеушілік туған мәселеде мені Өз рұқсатыңмен ақиқатқа бағытта. Шын мәнінде, Сен қалаған адамыңды тура жолға бағыттайсың»."}, {"c": 18, "ar": "((اللَّهُ أَكْبَرُ كَبِيرَاً، اللَّهُ أَكْبَرُ كَبِيراً، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً)) ثَلاثاً ((أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ، وَنَفْثِهِ، وَهَمْزِهِ)).", "n": 1, "a": "31", "ru": "«Аллах Велик, превелико! Аллах Велик, превелико! Аллах Велик, превелико! Хвала Аллаху обильная, хвала Аллаху обильная, хвала Аллаху обильная! И Слава Аллаху утром и вечером!» (трижды). «Прибегаю к Аллаху от шайтана: от его дуновения (высокомерия), его поплёвывания (порицаемой поэзии) и его наущения (одержимости)».", "kk": "«Аллаһ ұлы, шексіз ұлы! Аллаһ ұлы, шексіз ұлы! Аллаһ ұлы, шексіз ұлы! Аллаһқа мол мадақ болсын, Аллаһқа мол мадақ болсын, Аллаһқа мол мадақ болсын! Таңертең де, кешке де Аллаһ пәк!» (үш рет). «Шайтаннан: оның үрлеуінен (тәкаппарлығынан), түкіруінен (жаман өлеңінен) және түртуінен (есалаңдығынан) Аллаһқа сыйынамын»."}, {"c": 18, "ar": "((اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، [وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّمَواتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ لَكَ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ أَنْتَ مَلِكُ السَّمَوَاتِ وَالأَرْضِ] [وَلَكَ الْحَمْدُ] [أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَقَوْلُكَ الْحَقُّ، وَلِقاؤُكَ الْحَقُّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمحَمَّدٌ صلى الله عليه وسلم حَقٌّ، وَالسّاعَةُ حَقٌّ] [اللَّهُمَّ لَكَ أَسْلَمتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَبِكَ آمَنْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خاصَمْتُ، وَإِلَيْكَ حاكَمْتُ. فَاغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ] [وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي] [أَنْتَ المُقَدِّمُ، وَأَنْتَ المُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ] [أَنْتَ إِلَهِي لاَ إِلَهَ إِلاَّ أَنْتَ] [وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ])).", "n": 1, "a": "32", "ru": "«О Аллах, Тебе хвала! Ты — Свет небес, земли и тех, кто на них. И Тебе хвала, Ты — Поддерживающий небеса, землю и тех, кто на них. [И Тебе хвала, Ты — Господь небес, земли и тех, кто на них.] [И Тебе хвала, Тебе принадлежит власть над небесами, землёй и теми, кто на них.] [И Тебе хвала, Ты — Царь небес и земли.] [И Тебе хвала!] [Ты — Истина, Твоё обещание — истина, Твоё слово — истина, встреча с Тобой — истина, Рай — истина, Огонь — истина, пророки — истина, Мухаммад ﷺ — истина, и Час — истина.] [О Аллах, Тебе я покорился, на Тебя положился, в Тебя уверовал, к Тебе обратился, ради Тебя вступал в спор и к Твоему суду прибегал. Так прости мне то, что я совершил прежде, и то, что совершу после, то, что я скрыл, и то, что сделал явно,] [и то, о чём Ты знаешь лучше меня.] [Ты — Выдвигающий вперёд и Ты — Отодвигающий назад, нет божества, кроме Тебя.] [Ты — мой Бог, нет божества, кроме Тебя.] [И нет мощи и нет силы, кроме как у Аллаха.]»", "kk": "«Уа, Аллаһ, Саған мадақ! Сен – көктердің, жердің және олардағылардың Нұрысың. Саған мадақ! Сен – көктерді, жерді және олардағыларды ұстап, басқарып тұрушысың. [Саған мадақ! Сен – көктердің, жердің және олардағылардың Раббысысың.] [Саған мадақ! Көктердің, жердің және олардағылардың билігі Сенікі.] [Саған мадақ! Сен – көктер мен жердің Патшасысың.] [Саған мадақ!] [Сен – Ақиқатсың, уәдең – ақиқат, сөзің – ақиқат, Саған жолығу – ақиқат, жәннат – ақиқат, тозақ – ақиқат, пайғамбарлар – ақиқат, Мұхаммед ﷺ – ақиқат және Қиямет сағаты – ақиқат.] [Уа, Аллаһ, Саған бойсұндым, Саған тәуекел еттім, Саған иман келтірдім, Саған бет бұрдым, Сен үшін дауластым және үкімді Саған тапсырдым. Ендеше менің бұрын істегенімді де, кейін істегенімді де, жасырғанымды да, жария еткенімді де кешір,] [әрі Сен менен гөрі жақсырақ білетін нәрселерді де.] [Сен – Алға Шығарушысың және Сен – Кейін Қалдырушысың, Сенен басқа құдай жоқ.] [Сен – менің Құдайымсың, Сенен басқа құдай жоқ.] [Күш те, қуат та тек Аллаһ арқылы.]»"}, {"c": 19, "ar": "((سُبْحانَ رَبِّيَ الْعَظِيمِ)). ثلاث مرَّاتٍ.", "n": 3, "a": "33", "ru": "«Пречист мой Великий Господь». Трижды.", "kk": "«Ұлы Раббым пәк». Үш рет."}, {"c": 19, "ar": "((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)).", "n": 1, "a": "34", "ru": "«Пречист Ты, о Аллах, Господь наш, и хвала Тебе! О Аллах, прости меня».", "kk": "«Уа, Аллаһ, Раббымыз, Сен пәксің және Саған мадақ! Уа, Аллаһ, мені кешір»."}, {"c": 19, "ar": "((سُبُّوُحٌ، قُدُّوسٌ، رَبُّ المَلاَئِكَةِ وَالرُّوحِ)).", "n": 1, "a": "35", "ru": "«Пречистый, Святейший, Господь ангелов и Духа».", "kk": "«Аса Пәк, Аса Киелі, періштелер мен Рухтың Раббысы»."}, {"c": 19, "ar": "((اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَــــظْمِي، وَعَصَبِي، [وَمَا استَقَلَّتْ بِهِ قَدَمِي])).", "n": 1, "a": "36", "ru": "«О Аллах, Тебе я совершил поясной поклон, в Тебя уверовал и Тебе покорился. Смирились перед Тобой мой слух, моё зрение, мой мозг, мои кости, мои сухожилия [и всё, что держат мои ноги]».", "kk": "«Уа, Аллаһ, Саған рүкуғ жасадым, Саған иман келтірдім және Саған бойсұндым. Саған құлағым, көзім, миым, сүйегім және жүйкем мойынсұнды [әрі аяқтарым көтеріп тұрғанның бәрі де]»."}, {"c": 19, "ar": "((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)).", "n": 1, "a": "37", "ru": "«Пречист Обладатель всепобеждающего могущества, владычества, гордого величия и величия».", "kk": "«Жеңілмес құдірет, билік, асқақтық және ұлылық Иесі пәк»."}, {"c": 20, "ar": "((سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ)).", "n": 1, "a": "38", "ru": "«Аллах слышит того, кто воздал Ему хвалу».", "kk": "«Аллаһ Өзін мадақтағанды естиді»."}, {"c": 20, "ar": "((رَبَّنَا وَلَكَ الْحَمْدُ، حَمْداً كَثيراً طَيِّباً مُبارَكاً فِيهِ)).", "n": 1, "a": "39", "ru": "«Господь наш, и Тебе хвала — хвала обильная, благая и благословенная».", "kk": "«Раббымыз, Саған мадақ – көп, пәк әрі берекелі мадақ»."}, {"c": 20, "ar": "((مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ، وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ. أَهلَ الثَّناءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ. اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ)).", "n": 1, "a": "40", "ru": "«(Хвала,) наполняющая небеса и наполняющая землю, и то, что между ними, и наполняющая всё, что Ты пожелаешь помимо этого. (О Ты,) Достойный восхваления и славы! Самое достойное из того, что сказал раб, — а все мы Твои рабы: о Аллах, никто не удержит того, что Ты дал, и никто не даст того, что Ты удержал, и не принесёт пользы обладателю богатства перед Тобой его богатство».", "kk": "«Көктерді толтыратын, жерді толтыратын, екеуінің арасын толтыратын және бұдан кейін Сен қалаған әр нәрсені толтыратын (мадақ). Уа, мақтау мен ұлықтаудың Иесі! Құлдың айтқан сөзінің ең лайықтысы – ал біз бәріміз Сенің құлыңбыз: Уа, Аллаһ, Сен бергенді тоқтатушы жоқ, Сен тыйғанды беруші жоқ, әрі байлық иесіне Сенің алдыңда оның байлығы пайда бермейді»."}, {"c": 21, "ar": "((سُبْحَانَ رَبِّيَ الأَعْلَى)) ثلاث مرَّاتٍ.", "n": 3, "a": "41", "ru": "«Пречист мой Всевышний Господь». Трижды.", "kk": "«Ең Жоғары Раббым пәк». Үш рет."}, {"c": 21, "ar": "((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)).", "n": 1, "a": "42", "ru": "«Пречист Ты, о Аллах, Господь наш, и хвала Тебе! О Аллах, прости меня».", "kk": "«Уа, Аллаһ, Раббымыз, Сен пәксің және Саған мадақ! Уа, Аллаһ, мені кешір»."}, {"c": 21, "ar": "((سُبوحٌ، قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ)).", "n": 1, "a": "43", "ru": "«Пречистый, Святейший, Господь ангелов и Духа».", "kk": "«Аса Пәк, Аса Киелі, періштелер мен Рухтың Раббысы»."}, {"c": 21, "ar": "((اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسنُ الْخَالِقينَ)).", "n": 1, "a": "44", "ru": "«О Аллах, Тебе я совершил земной поклон, в Тебя уверовал и Тебе покорился. Моё лицо пало ниц перед Тем, Кто сотворил его, придал ему облик и отверз в нём слух и зрение. Благословен Аллах, Наилучший из творцов!»", "kk": "«Уа, Аллаһ, Саған сәжде жасадым, Саған иман келтірдім және Саған бойсұндым. Жүзім оны жаратқан, оған пішін берген және онда есту мен көруді ашқан Затқа сәжде етті. Жаратушылардың ең көркемі Аллаһ аса берекелі!»"}, {"c": 21, "ar": "((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)).", "n": 1, "a": "45", "ru": "«Пречист Обладатель всепобеждающего могущества, владычества, гордого величия и величия».", "kk": "«Жеңілмес құдірет, билік, асқақтық және ұлылық Иесі пәк»."}, {"c": 21, "ar": "((اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلاَنِيَّتَهُ وَسِرَّهُ)).", "n": 1, "a": "46", "ru": "«О Аллах, прости мне все мои грехи: малые и великие, первые и последние, явные и тайные».", "kk": "«Уа, Аллаһ, менің күнәмнің бәрін кешір: кішісін де, үлкенін де, алғашқысын да, соңғысын да, жариясын да, жасырынын да»."}, {"c": 21, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).", "n": 1, "a": "47", "ru": "«О Аллах, поистине, я прибегаю к Твоему довольству от Твоего гнева и к Твоему избавлению от Твоего наказания, и прибегаю к Тебе от Тебя. Не могу я исчислить хвалу Тебе: Ты таков, каким Сам Себя восхвалил».", "kk": "«Уа, Аллаһ, Сенің ашуыңнан разылығыңа, жазаңнан кешіріміңе сыйынамын және Сенен Өзіңе сыйынамын. Саған айтылатын мақтауды санап тауыса алмаймын: Сен Өзіңді Өзің қалай мақтасаң, солайсың»."}, {"c": 22, "ar": "((رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي)).", "n": 1, "a": "48", "ru": "«Господи, прости меня, Господи, прости меня».", "kk": "«Раббым, мені кешір, Раббым, мені кешір»."}, {"c": 22, "ar": "((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي)).", "n": 1, "a": "49", "ru": "«О Аллах, прости меня, помилуй меня, наставь меня, восполни мои недостатки, даруй мне благополучие, надели меня уделом и возвысь меня».", "kk": "«Уа, Аллаһ, мені кешір, маған рақым ет, мені тура жолға сал, кемшілігімді толықтыр, маған саулық бер, маған ризық бер және мені жоғары көтер»."}, {"c": 23, "ar": "((سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، ﴿فَتَبارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ﴾)).", "n": 1, "a": "50", "ru": "«Моё лицо пало ниц перед Тем, Кто сотворил его и отверз в нём слух и зрение Своей мощью и силой. «Благословен же Аллах, Наилучший из творцов!»»", "kk": "«Жүзім оны жаратқан және Өз күш-қуатымен онда есту мен көруді ашқан Затқа сәжде етті. «Жаратушылардың ең көркемі Аллаһ аса берекелі!»»"}, {"c": 23, "ar": "((اللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْراً، وَضَعْ عَنِّي بِهَا وِزْراً، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْراً، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ)).", "n": 1, "a": "51", "ru": "«О Аллах, запиши мне за него награду у Тебя, сними им с меня бремя (греха), сделай его для меня запасом у Тебя и прими его от меня, как Ты принял его от Твоего раба Давуда».", "kk": "«Уа, Аллаһ, ол үшін маған Өз құзырыңда сауап жаз, онымен менен күнә жүгін түсір, оны маған Өз құзырыңда қор қыл және оны құлың Дәуіттен қабыл еткеніңдей менен де қабыл ет»."}, {"c": 24, "ar": "((التَّحِيَّاتُ لِلَّهِ، وَالصَّلَواتُ، وَالطَّيِّباتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ)).", "n": 1, "a": "52", "ru": "Приветствия — Аллаху, а также молитвы и благие слова. Мир тебе, о Пророк, и милость Аллаха и Его благословения. Мир нам и праведным рабам Аллаха. Свидетельствую, что нет божества, кроме Аллаха, и свидетельствую, что Мухаммад — Его раб и Его посланник.", "kk": "Барлық сәлем-құрметтер, намаздар және игі сөздер Аллаһқа тән. Уа, Пайғамбар, саған сәлем, Аллаһтың рахымы және Оның берекеттері болсын. Бізге және Аллаһтың ізгі құлдарына сәлем болсын. Аллаһтан басқа құдай жоқ екеніне куәлік беремін және Мұхаммед — Оның құлы әрі елшісі екеніне куәлік беремін."}, {"c": 25, "ar": "((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ)).", "n": 1, "a": "53", "ru": "О Аллах, благослови Мухаммада и семейство Мухаммада, как Ты благословил Ибрахима и семейство Ибрахима, — поистине, Ты Достохвальный, Славный. О Аллах, ниспошли благодать Мухаммаду и семейству Мухаммада, как Ты ниспослал благодать Ибрахиму и семейству Ибрахима, — поистине, Ты Достохвальный, Славный.", "kk": "Уа, Аллаһ, Ибраһимге және Ибраһимнің әулетіне салауат еткеніңдей, Мұхаммедке және Мұхаммедтің әулетіне салауат ет. Шүбәсіз, Сен — Мақтаулы, Ұлықсың. Уа, Аллаһ, Ибраһимге және Ибраһимнің әулетіне береке бергеніңдей, Мұхаммедке және Мұхаммедтің әулетіне береке бер. Шүбәсіз, Сен — Мақтаулы, Ұлықсың."}, {"c": 25, "ar": "((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ. وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى أَزْواجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ. إِنَّكَ حَمِيدٌ مَجِيدٌ)).", "n": 1, "a": "54", "ru": "О Аллах, благослови Мухаммада, его жён и его потомство, как Ты благословил семейство Ибрахима, и ниспошли благодать Мухаммаду, его жёнам и его потомству, как Ты ниспослал благодать семейству Ибрахима. Поистине, Ты Достохвальный, Славный.", "kk": "Уа, Аллаһ, Ибраһимнің әулетіне салауат еткеніңдей, Мұхаммедке, оның жұбайларына және ұрпағына салауат ет. Ибраһимнің әулетіне береке бергеніңдей, Мұхаммедке, оның жұбайларына және ұрпағына береке бер. Шүбәсіз, Сен — Мақтаулы, Ұлықсың."}, {"c": 26, "ar": "((اللَّهُــمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ)).", "n": 1, "a": "55", "ru": "О Аллах, поистине, я прибегаю к Тебе от мучений могилы, от мучений Ада, от испытания жизни и смерти и от зла испытания Лжемессии (аль-Масиха ад-Даджжаля).", "kk": "Уа, Аллаһ, шынында мен Сенен қабір азабынан, Жаһаннам азабынан, өмір мен өлім пітнесінен және Мәсих Дажжал пітнесінің жамандығынан пана тілеймін."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ)).", "n": 1, "a": "56", "ru": "О Аллах, поистине, я прибегаю к Тебе от мучений могилы, прибегаю к Тебе от испытания Лжемессии (аль-Масиха ад-Даджжаля) и прибегаю к Тебе от испытания жизни и смерти. О Аллах, поистине, я прибегаю к Тебе от греха и от долга.", "kk": "Уа, Аллаһ, шынында мен Сенен қабір азабынан пана тілеймін, Сенен Мәсих Дажжалдың пітнесінен пана тілеймін және Сенен өмір мен өлім пітнесінен пана тілеймін. Уа, Аллаһ, шынында мен Сенен күнәдан және қарыздан пана тілеймін."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْماً كَثِيراً، وَلاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الغَفورُ الرَّحيمُ)).", "n": 1, "a": "57", "ru": "О Аллах, поистине, я много притеснял самого себя, а прощает грехи только Ты. Так прости же меня прощением от Тебя и помилуй меня, — поистине, Ты Прощающий, Милосердный.", "kk": "Уа, Аллаһ, шынында мен өзіме көп зұлымдық жасадым, ал күнәларды тек Сен ғана кешіресің. Ендеше, мені Өз тарапыңнан кешіріммен кешір және маған рахым ет. Шүбәсіз, Сен — аса Кешірімді, ерекше Мейірімдісің."}, {"c": 26, "ar": "((اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ)).", "n": 1, "a": "58", "ru": "О Аллах, прости мне то, что я совершил прежде, и то, что совершил позже, то, что я делал тайно, и то, что делал явно, то, в чём я преступил меру, и то, о чём Ты знаешь лучше меня. Ты — Выдвигающий вперёд, и Ты — Отодвигающий назад, нет божества, кроме Тебя.", "kk": "Уа, Аллаһ, менің бұрын істегенімді де, кейін істегенімді де, жасырын істегенімді де, ашық істегенімді де, шектен шыққанымды да және менен гөрі Өзің жақсырақ білетін нәрсені де кешір. Сен — Алға Шығарушысың, Сен — Кейінге Қалдырушысың. Сенен басқа құдай жоқ."}, {"c": 26, "ar": "((اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبادَتِكَ)).", "n": 1, "a": "59", "ru": "О Аллах, помоги мне поминать Тебя, благодарить Тебя и наилучшим образом поклоняться Тебе.", "kk": "Уа, Аллаһ, Сені зікір етуге, Саған шүкір етуге және Саған көркем түрде құлшылық етуге маған жәрдем бер."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ)).", "n": 1, "a": "60", "ru": "О Аллах, поистине, я прибегаю к Тебе от скупости, прибегаю к Тебе от трусости, прибегаю к Тебе от того, чтобы быть возвращённым к самому жалкому возрасту, и прибегаю к Тебе от испытания этого мира и от мучений могилы.", "kk": "Уа, Аллаһ, шынында мен Сенен сараңдықтан пана тілеймін, Сенен қорқақтықтан пана тілеймін, Сенен өмірдің ең нашар шағына қайтарылудан пана тілеймін және Сенен дүние пітнесінен әрі қабір азабынан пана тілеймін."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).", "n": 1, "a": "61", "ru": "О Аллах, поистине, я прошу Тебя о Рае и прибегаю к Тебе от Огня.", "kk": "Уа, Аллаһ, шынында мен Сенен жәннатты сұраймын және Сенен тозақтан пана тілеймін."}, {"c": 26, "ar": "((اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ، وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْــــأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ، وَلاَ فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ)).", "n": 1, "a": "62", "ru": "О Аллах, Твоим знанием сокровенного и Твоим могуществом над творениями — сохраняй мне жизнь, пока Ты знаешь, что жизнь для меня благо, и упокой меня, когда Ты знаешь, что смерть для меня благо. О Аллах, я прошу Тебя о страхе перед Тобой втайне и явно, прошу Тебя о слове истины в довольстве и в гневе, прошу Тебя об умеренности в богатстве и в бедности, прошу Тебя о блаженстве, которое не иссякнет, прошу Тебя об отраде глаз, которая не прервётся, прошу Тебя о довольстве после свершения Твоего решения, прошу Тебя о прохладе жизни после смерти, прошу Тебя о наслаждении взглядом на Твой Лик и о стремлении к встрече с Тобой — без вредящего бедствия и без вводящего в заблуждение испытания. О Аллах, укрась нас украшением веры и сделай нас ведущими прямым путём и идущими прямым путём.", "kk": "Уа, Аллаһ, ғайыпты білуіңмен және жаратылысқа құдіретің жетуімен, өмір мен үшін жақсы екенін білгеніңше мені тірі қалдыр, ал өлім мен үшін жақсы екенін білгенде жанымды ал. Уа, Аллаһ, мен Сенен жасырында да, ашықта да Өзіңнен қорқуды сұраймын; разылықта да, ашуда да ақиқат сөзді сұраймын; байлықта да, кедейлікте де орташалықты сұраймын; таусылмайтын нығметті сұраймын; үзілмейтін көз қуанышын сұраймын; үкімің орындалғаннан кейін разылықты сұраймын; өлгеннен кейінгі салқын (рахат) тіршілікті сұраймын; Жүзіңе қараудың ләззатын және зиян келтіретін қиыншылықсыз, адастыратын пітнесіз Саған жолығуға деген құштарлықты сұраймын. Уа, Аллаһ, бізді иманның зейнетімен безендір және бізді тура жолға бастаушы әрі тура жолдағы адамдар қыл."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يولَدْ، وَلَمْ يَكنْ لَهُ كُفُواً أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِّيمُ)).", "n": 1, "a": "63", "ru": "О Аллах, поистине, я прошу Тебя, о Аллах, — ведь Ты Единый, Единственный, Самодостаточный, Который не родил и не был рождён, и нет никого, равного Ему, — простить мне мои грехи. Поистине, Ты — Прощающий, Милосердный.", "kk": "Уа, Аллаһ, Сенің Жалғыз, Бір, Самад (Мұқтажсыз), тумаған әрі туылмаған және Оған ешкім тең болмаған Ие екеніңмен, уа, Аллаһ, шынында мен Сенен күнәларымды кешіруіңді сұраймын. Шүбәсіз, Сен — аса Кешірімді, ерекше Мейірімдісің."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).", "n": 1, "a": "64", "ru": "О Аллах, поистине, я прошу Тебя — ведь Тебе принадлежит хвала, нет божества, кроме Тебя, Одного, нет у Тебя сотоварища, Ты — Дарующий блага (аль-Маннан). О Создатель небес и земли, о Обладатель величия и щедрости, о Живой, о Вседержитель! Поистине, я прошу Тебя о Рае и прибегаю к Тебе от Огня.", "kk": "Уа, Аллаһ, мадақ Саған тән екенімен, Сенен басқа құдай жоқ, Сен жалғызсың, Сенің серігің жоқ, Сен — Мәннан (нығметтерді мол Сыйлаушы) екенімен шынында мен Сенен сұраймын. Уа, көктер мен жерді жоқтан Жаратушы, уа, Ұлылық пен Құрмет Иесі, уа, Тірі, уа, Мәңгі Тұрушы! Шынында мен Сенен жәннатты сұраймын және Сенен тозақтан пана тілеймін."}, {"c": 26, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ)) .", "n": 1, "a": "65", "ru": "О Аллах, поистине, я прошу Тебя тем, что свидетельствую: Ты — Аллах, нет божества, кроме Тебя, Единственный, Самодостаточный, Который не родил и не был рождён, и нет никого, равного Ему.", "kk": "Уа, Аллаһ, Сенің Аллаһ екеніңе, Сенен басқа құдай жоқ екеніне, Сенің Бір, Самад (Мұқтажсыз), тумаған әрі туылмаған және Оған ешкім тең болмаған Ие екеніңе куәлік беретінім арқылы шынында мен Сенен сұраймын."}, {"c": 27, "ar": "((أَسْتَغْفِرُ اللَّهَ (ثَلاَثَاً) اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ)).", "n": 1, "a": "66", "ru": "Прошу прощения у Аллаха (трижды). О Аллах, Ты — Мир (ас-Салям), и от Тебя мир. Благословен Ты, о Обладатель величия и щедрости.", "kk": "Аллаһтан кешірім сұраймын (үш рет). Уа, Аллаһ, Сен — Сәләмсің, амандық та Сенен. Уа, Ұлылық пен Құрмет Иесі, Сен берекелісің."}, {"c": 27, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [ثلاثاً]، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الجَدُّ)).", "n": 1, "a": "67", "ru": "Нет божества, кроме Аллаха, Одного, нет у Него сотоварища. Ему принадлежит власть, Ему принадлежит хвала, и Он над всякой вещью мощен [трижды]. О Аллах, никто не удержит того, что Ты дал, и никто не даст того, что Ты удержал, и не поможет обладателю богатства и положения перед Тобой его богатство.", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Оған тән, мадақ Оған тән және Ол барлық нәрсеге құдіретті [үш рет]. Уа, Аллаһ, Сен бергенді тосушы жоқ, Сен тосқанды беруші жоқ және байлық пен мәртебе иесіне Сенің алдыңда оның байлығы пайда бермейді."}, {"c": 27, "ar": "((لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ, لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلَهَ إِلاَّ اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الكَافِرُونَ)).", "n": 1, "a": "68", "ru": "Нет божества, кроме Аллаха, Одного, нет у Него сотоварища. Ему принадлежит власть, Ему принадлежит хвала, и Он над всякой вещью мощен. Нет мощи и силы, кроме как у Аллаха. Нет божества, кроме Аллаха, и мы не поклоняемся никому, кроме Него. Ему принадлежат блага, Ему принадлежит милость, и Ему принадлежит прекрасная хвала. Нет божества, кроме Аллаха, — мы искренни перед Ним в религии, даже если это ненавистно неверующим.", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Оған тән, мадақ Оған тән және Ол барлық нәрсеге құдіретті. Күш те, қуат та тек Аллаһ арқылы ғана. Аллаһтан басқа құдай жоқ және біз тек Оған ғана құлшылық етеміз. Нығмет Оған тән, кеңшілік Оған тән және көркем мақтау Оған тән. Аллаһтан басқа құдай жоқ, кәпірлер жақтырмаса да, біз дінді шынайы түрде тек Оған ғана арнаймыз."}, {"c": 27, "ar": "((سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ (ثلاثاً وثلاثين) لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).", "n": 33, "a": "69", "ru": "Слава Аллаху, хвала Аллаху, Аллах Велик (тридцать три раза). Нет божества, кроме Аллаха, Одного, нет у Него сотоварища. Ему принадлежит власть, Ему принадлежит хвала, и Он над всякой вещью мощен.", "kk": "Аллаһ пәк, Аллаһқа мадақ, Аллаһ ұлы (отыз үш рет). Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Оған тән, мадақ Оған тән және Ол барлық нәрсеге құдіретті."}, {"c": 27, "ar": "بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ* اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾، بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾،بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ بَعْدَ كُلِّ صَلاَةٍ.", "n": 1, "a": "70", "ru": "Во имя Аллаха, Милостивого, Милосердного. «Скажи: Он — Аллах Единый. Аллах Самодостаточный. Он не родил и не был рождён, и нет никого, равного Ему». Во имя Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу рассвета от зла того, что Он сотворил, от зла мрака, когда он наступает, от зла дующих на узлы и от зла завистника, когда он завидует». Во имя Аллаха, Милостивого, Милосердного. «Скажи: прибегаю к Господу людей, Царю людей, Богу людей, от зла искусителя, отступающего и скрывающегося, который нашёптывает в груди людей, — из джиннов и людей». — После каждой молитвы.", "kk": "Аса Қамқор, ерекше Мейірімді Аллаһтың атымен. «Айт: Ол — Аллаһ, Жалғыз. Аллаһ — Самад (Мұқтажсыз). Ол тумаған әрі туылмаған. Әрі Оған ешкім тең емес». Аса Қамқор, ерекше Мейірімді Аллаһтың атымен. «Айт: Таңның Раббысынан пана тілеймін — Ол жаратқан нәрселердің жамандығынан, басып келген қараңғылықтың жамандығынан, түйіндерге үрлеушілердің жамандығынан және күндеген кездегі күншілдің жамандығынан». Аса Қамқор, ерекше Мейірімді Аллаһтың атымен. «Айт: Адамдардың Раббысынан, адамдардың Патшасынан, адамдардың Құдайынан пана тілеймін — адамдардың көкірегіне күбір салатын, жасырынып шегінетін азғырушының жамандығынан; ол жындардан да, адамдардан да болады». — Әр намаздан кейін."}, {"c": 27, "ar": "﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ عَقِبَ كلِّ صَلاَةٍ.", "n": 1, "a": "71", "ru": "«Аллах — нет божества, кроме Него, Живого, Вседержителя. Не овладевает Им ни дремота, ни сон. Ему принадлежит то, что на небесах, и то, что на земле. Кто заступится перед Ним иначе, как с Его дозволения? Он знает то, что перед ними, и то, что позади них, а они не постигают ничего из Его знания, кроме того, что Он пожелает. Его Курси объемлет небеса и землю, и не тяготит Его оберегание их. Он — Высокий, Великий». — После каждой молитвы.", "kk": "«Аллаһ — Одан басқа құдай жоқ, Ол — Тірі, Мәңгі Тұрушы. Оны мүлгу де, ұйқы да баспайды. Көктердегі және жердегі нәрселер Оған тән. Оның рұқсатынсыз Оның алдында кім шапағат ете алады? Ол олардың алдындағыны да, артындағыны да біледі. Ал олар Оның ілімінен Ол қалағаннан басқа еш нәрсені қамти алмайды. Оның Күрсісі көктер мен жерді қамтыған. Ол екеуін сақтау Оны шаршатпайды. Ол — аса Жоғары, аса Ұлы». — Әр намаздан кейін."}, {"c": 27, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) عَشْرَ مَرّاتٍ بَعْدَ صَلاةِ الْمَغْرِبِ وَالصُّبْحِ.", "n": 10, "a": "72", "ru": "Нет божества, кроме Аллаха, Одного, нет у Него сотоварища. Ему принадлежит власть, Ему принадлежит хвала, Он оживляет и умерщвляет, и Он над всякой вещью мощен. — Десять раз после вечерней (магриб) и утренней молитвы.", "kk": "Аллаһтан басқа құдай жоқ, Ол жалғыз, Оның серігі жоқ. Билік Оған тән, мадақ Оған тән, Ол тірілтеді әрі өлтіреді және Ол барлық нәрсеге құдіретті. — Ақшам және таң намазынан кейін он рет."}, {"c": 27, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) بَعْدَ السّلامِ مِنْ صَلاَةِ الفَجْرِ.", "n": 1, "a": "73", "ru": "О Аллах, поистине, я прошу Тебя о полезном знании, благом уделе и принятом деянии. — После завершающего приветствия (салама) утренней молитвы.", "kk": "Уа, Аллаһ, шынында мен Сенен пайдалы ілім, адал әрі пәк ризық және қабыл болған амал сұраймын. — Таң намазының сәлемінен кейін."}, {"c": 28, "ar": "قَالَ جَابرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ رسُولُ اللَّهِ صلى الله عليه وسلم يُعَلِّمُنَا الْاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: ((إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لْيَقُلْ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ؛ فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ، وَتَعْلَمُ وَلاَ أَعْلَمُ، وَأَنْتَ عَلاَّمُ الغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأمْرَ - وَيُسَمِّي حَاجَتَهُ - خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ - فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ – فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ)).وَمَا نَدِمَ مَنِ اسْتَخَارَ الْخَالِقَ، وَشَاوَرَ الْمَخْلُوقِينَ الْمُؤْمِنِينَ وَتَثَبَّتَ فِي أَمْرِهِ، فَقَدْ قَالَ اللَّه تعالى: ﴿وَشاوِرْهُمْ فِي الْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ﴾ .", "n": 1, "a": "74", "ru": "Джабир ибн Абдуллах (да будет доволен Аллах ими обоими) сказал: Посланник Аллаха ﷺ учил нас истихаре во всех делах так же, как учил нас суре из Корана. Он говорил: «Когда кто-нибудь из вас вознамерится сделать что-либо, пусть совершит два ракаата помимо обязательной молитвы, а затем скажет: О Аллах, я прошу Тебя выбрать для меня лучшее Твоим знанием, прошу Тебя наделить меня силой Твоим могуществом и прошу Тебя о Твоей великой милости. Ведь Ты можешь, а я не могу, Ты знаешь, а я не знаю, и Ты — Знающий всё сокровенное. О Аллах, если Ты знаешь, что это дело — и пусть назовёт свою нужду — благо для меня в моей религии, в моей жизни и в исходе моего дела, — или он сказал: в ближайшем и отдалённом из моего дела, — то предопредели его мне, облегчи его для меня, а затем благослови меня в нём. А если Ты знаешь, что это дело — зло для меня в моей религии, в моей жизни и в исходе моего дела, — или он сказал: в ближайшем и отдалённом из моего дела, — то отврати его от меня и отврати меня от него, и предопредели мне благо, где бы оно ни было, а затем сделай меня довольным им». И никогда не сожалел тот, кто просил Творца о выборе, советовался с верующими из творений и проявлял основательность в своём деле, ведь Всевышний Аллах сказал: «И советуйся с ними о деле, а когда примешь решение, уповай на Аллаха».", "kk": "Жәбір ибн Абдуллаһ (Аллаһ екеуіне де разы болсын) былай деді: Аллаһтың елшісі ﷺ бізге Құраннан сүре үйреткендей, барлық істерде истихараны үйрететін. Ол былай дейтін: «Сендердің біреулерің бір істі ниет етсе, парыздан басқа екі рәкағат намаз оқысын, содан кейін былай десін: Уа, Аллаһ, Сенің іліміңмен Сенен жақсысын таңдап беруіңді сұраймын, Сенің құдіретіңмен Сенен күш-қабілет сұраймын және Сенің ұлы кеңшілігіңнен сұраймын. Өйткені Сенің күшің жетеді, ал менің күшім жетпейді; Сен білесің, ал мен білмеймін және Сен — ғайыптарды толық Білушісің. Уа, Аллаһ, егер осы іс — қажетінің атын атайды — менің дінім, тіршілігім және ісімнің соңы үшін — немесе: ісімнің жақыны мен алысы үшін деді — жақсы екенін білсең, оны маған тағдыр ет, оны маған жеңілдет, сосын оны маған берекелі ет. Ал егер осы іс менің дінім, тіршілігім және ісімнің соңы үшін — немесе: ісімнің жақыны мен алысы үшін деді — жаман екенін білсең, оны менен бұр, мені одан бұр және жақсылық қайда болса да, оны маған тағдыр ет, сосын мені соған разы қыл». Жаратушыдан жақсысын таңдап беруді сұраған, жаратылыстардың ішіндегі мүміндермен кеңескен және ісінде нық болған адам ешқашан өкінбеген. Өйткені Аллаһ Тағала: «Іс жайында олармен кеңес. Ал бір шешімге бекінгенде, Аллаһқа тәуекел ет» деген."}, {"c": 29, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزيزُ الْغَفَّارُ)).", "n": 1, "a": "112", "ru": "Нет божества, кроме Аллаха, Единого, Покоряющего, Господа небес, земли и того, что между ними, Могущественного, Многопрощающего.", "kk": "Аллаһтан басқа құдай жоқ, Ол — Жалғыз, Қаһар Иесі, көктердің, жердің және екеуінің арасындағының Раббысы, аса Құдіретті, Кешірімі мол."}, {"c": 30, "ar": "((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّياطِينِ وَأَنْ يَحْضُرُونِ)).", "n": 1, "a": "113", "ru": "Прибегаю к совершенным словам Аллаха от Его гнева и Его наказания, от зла Его рабов, от наущений шайтанов и от того, чтобы они явились ко мне.", "kk": "Аллаһтың кемел сөздерімен Оның ашуынан, Оның жазасынан, Оның құлдарының жамандығынан, шайтандардың азғыруларынан және олардың маған келуінен пана тілеймін."}, {"c": 31, "ar": "[ (يَنْفُثُ عَنْ يَسَارِهِ (ثلاثاً)) - (يَسْتَعِيذُ بِاللَّهِ مِنَ الشَّيطَانِ وَمِنْ شَرِّ مَا رَأَى (ثَلاَثَ مَرَّاتٍ)) - ((لاَ يُحَدِّثْ بِهَا أَحَداً)) - ((يَــتَحَوَّلُ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ)) ]", "n": 3, "a": "114", "ru": "[ (Слегка сплёвывает влево (трижды)) — (просит у Аллаха защиты от шайтана и от зла того, что увидел (три раза)) — (никому о нём не рассказывает) — (переворачивается с того бока, на котором лежал) ]", "kk": "[ (Сол жағына жеңіл түкіргендей үрлейді (үш рет)) — (шайтаннан және көрген нәрсесінің жамандығынан Аллаһқа сыйынып, пана тілейді (үш рет)) — (оны ешкімге айтпайды) — (жатқан жамбасынан екінші жағына аунап жатады) ]"}, {"c": 31, "ar": "((ويَقُومُ يُصَلِّي إِنْ أَرَادَ ذَلِكَ)).", "n": 1, "a": "115", "ru": "И встаёт помолиться, если пожелает этого.", "kk": "Әрі қаласа, тұрып намаз оқиды."}, {"c": 32, "ar": "((اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ، إِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ، [وَلاَ يَعِزُّ مَنْ عَادَيْتَ]، تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ)).", "n": 1, "a": "116", "ru": "О Аллах, наставь меня на прямой путь среди тех, кого Ты наставил, даруй мне благополучие среди тех, кому Ты даровал благополучие, возьми меня под Своё покровительство среди тех, кого Ты взял под покровительство, благослови меня в том, что Ты даровал, и убереги меня от зла того, что Ты предрешил, — ведь Ты решаешь, и никто не выносит решения против Тебя. Поистине, не будет унижен тот, кому Ты покровительствуешь, [и не будет славен тот, с кем Ты враждуешь]. Благословен Ты, Господь наш, и Превознесён.", "kk": "Уа, Аллаһ, Сен тура жолға салғандардың қатарында мені де тура жолға сал, Сен саулық бергендердің қатарында маған да саулық бер, Сен қамқорлығыңа алғандардың қатарында мені де қамқорлығыңа ал, бергеніңе маған береке бер және Сен үкім еткен нәрсенің жамандығынан мені сақта. Өйткені Сен үкім етесің, ал Саған қарсы ешкім үкім шығара алмайды. Шүбәсіз, Сен дос тұтқан адам қор болмайды, [Сен жау тұтқан адам абыройлы болмайды]. Раббымыз, Сен берекелісің әрі аса Жоғарысың."}, {"c": 32, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُــــوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).", "n": 1, "a": "117", "ru": "О Аллах, поистине, я прибегаю к Твоему довольству от Твоего гнева, к Твоему избавлению от Твоего наказания, и прибегаю к Тебе от Тебя. Я не в силах исчислить хвалу Тебе — Ты таков, каким Ты Сам восхвалил Себя.", "kk": "Уа, Аллаһ, шынында мен Сенің разылығыңмен ашуыңнан, Сенің кешіріп аман қылуыңмен жазаңнан пана тілеймін және Сенен Өзіңе пана тілеймін. Мен Саған айтылатын мақтауды санап тауыса алмаймын. Сен Өзіңді Өзің мақтағандайсың."}, {"c": 32, "ar": "((اللَّهُمَّ إِيَّاكَ نعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالكَافِرِينَ مُلْحَقٌ. اللَّهُمَّ إِنَّا نَسْتَعينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلاَ نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفرُكَ)).", "n": 1, "a": "118", "ru": "О Аллах, Тебе мы поклоняемся, Тебе молимся и перед Тобой падаем ниц, к Тебе стремимся и спешим. Надеемся на Твою милость и страшимся Твоего наказания, — поистине, Твоё наказание постигнет неверующих. О Аллах, поистине, мы просим Тебя о помощи, просим у Тебя прощения, восхваляем Тебя благом, не проявляем к Тебе неблагодарности, веруем в Тебя, смиряемся перед Тобой и отрекаемся от того, кто не верует в Тебя.", "kk": "Уа, Аллаһ, тек Саған ғана құлшылық етеміз, Саған намаз оқып, Саған сәжде етеміз, Саған қарай ұмтылып, асығамыз. Сенің рахымыңнан үміт етеміз, азабыңнан қорқамыз. Шүбәсіз, Сенің азабың кәпірлерге жетеді. Уа, Аллаһ, шынында біз Сенен жәрдем сұраймыз, Сенен кешірім тілейміз, Сені ізгілікпен мақтаймыз, Саған шүкірсіздік етпейміз, Саған иман келтіреміз, Саған бас иеміз және Сені мойындамайтын адамнан бас тартамыз."}, {"c": 33, "ar": "((سُبْحَانَ المَلِكِ القُدُّوسِ)) ثلاثَ مرَّاتٍ والثَّالِثَةُ يَجْهَرُ بها ويَمُدُّ بها صَوتَهُ يقولُ: [رَبِّ الْمَلاَئِكَةِ وَالرُّوحِ])).", "n": 3, "a": "119", "ru": "«Слава Царю Пресвятому» — три раза, причём в третий раз произносит это громко, протягивая голос, и говорит: [Господу ангелов и Духа].", "kk": "«Құддус (аса Пәк) Патша пәк» — үш рет, ал үшіншісін дауыстап, даусын созып айтады да, былай дейді: [періштелер мен Рухтың Раббысы]."}, {"c": 34, "ar": "((اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُــــلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلاَءَ حُزْنِي، وَذَهَابَ هَمِّي)).", "n": 1, "a": "120", "ru": "О Аллах, поистине, я Твой раб, сын Твоего раба, сын Твоей рабыни. Мой хохол — в Твоей руке, Твоё решение исполняется надо мной, справедливо Твоё предопределение обо мне. Я прошу Тебя каждым Твоим именем, которым Ты назвал Себя, или ниспослал его в Своём Писании, или научил ему кого-либо из Своих творений, или оставил его сокрытым у Себя в знании сокровенного, — сделать Коран весной моего сердца, светом моей груди, рассеянием моей печали и избавлением от моей заботы.", "kk": "Уа, Аллаһ, шынында мен Сенің құлыңмын, құлыңның ұлымын, күңіңнің ұлымын. Маңдай шашым Сенің қолыңда, Сенің үкімің мен жайында жүзеге асады, Сенің мен жайлы шешімің әділ. Сенен Өзіңе тән, Өзіңді сол атпен атаған немесе Кітабыңда түсірген, немесе жаратылысыңнан біреуге үйреткен, немесе Өз қасыңдағы ғайып ілімінде Өзіңе ғана қалдырған әрбір есіміңмен сұраймын: Құранды жүрегімнің көктемі, көкірегімнің нұры, қайғымның сейілуі және уайымымның кетуі ет."}, {"c": 34, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).", "n": 1, "a": "121", "ru": "О Аллах, поистине, я прибегаю к Тебе от заботы и печали, от бессилия и лени, от скупости и трусости, от бремени долга и от одоления людьми.", "kk": "Уа, Аллаһ, шынында мен Сенен уайым мен қайғыдан, дәрменсіздік пен жалқаулықтан, сараңдық пен қорқақтықтан, қарыздың ауыртпалығынан және адамдардың үстемдігінен пана тілеймін."}, {"c": 35, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ)).", "n": 1, "a": "122", "ru": "Нет божества, кроме Аллаха, Великого, Кроткого. Нет божества, кроме Аллаха, Господа великого Трона. Нет божества, кроме Аллаха, Господа небес, Господа земли и Господа благородного Трона.", "kk": "Аллаһтан басқа құдай жоқ, Ол — аса Ұлы, аса Ұстамды. Аллаһтан басқа құдай жоқ, Ол — ұлы Аршының Раббысы. Аллаһтан басқа құдай жоқ, Ол — көктердің Раббысы, жердің Раббысы және құрметті Аршының Раббысы."}, {"c": 35, "ar": "((اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ)).", "n": 1, "a": "123", "ru": "О Аллах, на Твою милость я надеюсь, так не оставляй же меня самому себе ни на мгновение ока и приведи в порядок все мои дела. Нет божества, кроме Тебя.", "kk": "Уа, Аллаһ, Сенің рахымыңнан үміттенемін. Ендеше, мені көзді ашып-жұмғандай сәтке де өз-өзіме тапсырма және менің барлық ісімді түзе. Сенен басқа құдай жоқ."}, {"c": 35, "ar": "((لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظّالِمِينَ)).", "n": 1, "a": "124", "ru": "Нет божества, кроме Тебя, пречист Ты! Поистине, я был из числа несправедливых.", "kk": "Сенен басқа құдай жоқ, Сен пәксің! Шынында мен залымдардан болдым."}, {"c": 35, "ar": "((اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئاً)).", "n": 1, "a": "125", "ru": "Аллах, Аллах — мой Господь, я ничего не придаю Ему в сотоварищи.", "kk": "Аллаһ, Аллаһ — менің Раббым, мен Оған ешнәрсені серік қоспаймын."}, {"c": 36, "ar": "((اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِم، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ)).", "n": 1, "a": "126", "ru": "О Аллах, поистине, мы ставим Тебя против их глоток и прибегаем к Тебе от их зла.", "kk": "Уа, Аллаһ, шынында біз Сені олардың кеудесіне қарсы қоямыз және олардың жамандықтарынан Сенен пана тілейміз."}, {"c": 36, "ar": "((اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقاتِلُ)).", "n": 1, "a": "127", "ru": "О Аллах, Ты — моя опора, и Ты — мой помощник. Тобой я действую, Тобой нападаю и Тобой сражаюсь.", "kk": "Уа, Аллаһ, Сен — менің тірегімсің, Сен — менің жәрдемшімсің. Сенің жәрдеміңмен айла қыламын, Сенің жәрдеміңмен шабуыл жасаймын және Сенің жәрдеміңмен соғысамын."}, {"c": 36, "ar": "((حَسْبُنا اللَّهُ وَنِعْمَ الْوَكِيلُ)).", "n": 1, "a": "128", "ru": "Достаточно нам Аллаха, и как прекрасен Он как Попечитель!", "kk": "Бізге Аллаһ жеткілікті, Ол — нендей жақсы Уәкіл!"}, {"c": 37, "ar": "((اللَّهُمَّ ربَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ بْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ)).", "n": 1, "a": "129", "ru": "О Аллах, Господь семи небес и Господь великого Трона, будь мне защитником от такого-то, сына такого-то, и от его сторонников из Твоих творений, чтобы никто из них не поспешил причинить мне зло и не притеснил меня. Могуч тот, кто под Твоей защитой, велика хвала Тебе, и нет божества, кроме Тебя.", "kk": "Уа, Аллаһ, жеті көктің Раббысы және ұлы Аршының Раббысы, пәленшенің ұлы пәленшеден және оның Сенің жаратылыстарыңнан болған жақтастарынан маған қорғаушы бол, олардың ешқайсысы маған жамандық жасауға асықпасын әрі шектен шықпасын. Сенің қорғауыңдағы адам мықты, Саған айтылған мақтау ұлы және Сенен басқа құдай жоқ."}, {"c": 37, "ar": "((اللَّهُ أَكْبَرُ، اللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعاً، اللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ، الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلاَّ بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلاَنٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنْ الْجِنِّ وَالإِنْسِ، اللَّهُمَّ كُنْ لِي جَاراً مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ)) (ثلاثَ مرَّاتٍ).", "n": 3, "a": "130", "ru": "Аллах Велик, Аллах могущественнее всех Своих творений, Аллах могущественнее того, чего я страшусь и остерегаюсь. Прибегаю к Аллаху, кроме Которого нет божества, Удерживающему семь небес от падения на землю иначе, как с Его дозволения, — от зла Твоего раба такого-то, его воинов, его последователей и его приверженцев из джиннов и людей. О Аллах, будь мне защитником от их зла. Велика хвала Тебе, могуч тот, кто под Твоей защитой, благословенно Твоё имя, и нет божества, помимо Тебя. (Три раза.)", "kk": "Аллаһ ұлы, Аллаһ барлық жаратылысынан құдіреттірек, Аллаһ мен қорқатын және сақтанатын нәрседен құдіреттірек. Өзінен басқа құдай жоқ, жеті көкті Өз рұқсатынсыз жерге құлап түсуден ұстап тұрған Аллаһтан Сенің пәленше құлыңның, оның әскерлерінің, ізбасарларының және жақтастарының — жындар мен адамдардан болған — жамандығынан пана тілеймін. Уа, Аллаһ, олардың жамандығынан маған қорғаушы бол. Саған айтылған мақтау ұлы, Сенің қорғауыңдағы адам мықты, есімің берекелі және Сенен басқа құдай жоқ. (Үш рет.)"}, {"c": 38, "ar": "((اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهزِمْهُمْ وَزَلْزِلْهُمْ)).", "n": 1, "a": "131", "ru": "О Аллах, ниспославший Писание, скорый в расчёте, разбей союзные полчища! О Аллах, разбей их и потряси их!", "kk": "Уа, Аллаһ, Кітапты түсіруші, есепті тез алушы, біріккен жау топтарын жеңіліске ұшырат! Уа, Аллаһ, оларды жеңіліске ұшыратып, тітірент!"}, {"c": 39, "ar": "((اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ)).", "n": 1, "a": "132", "ru": "О Аллах, избавь меня от них чем пожелаешь.", "kk": "Уа, Аллаһ, оларға қарсы Өзің қалаған нәрсемен маған жеткілікті бол."}, {"c": 40, "ar": "((يَسْتَعِيذُ بِاللَّهِ و يَنْتَهِي عَمَّا شك فِيهِ)).", "n": 1, "a": "133", "ru": "Пусть он попросит у Аллаха защиты и отступится от того, в чём у него возникло сомнение.", "kk": "Аллаһқа сыйынып, күмәнданған нәрсесінен тыйылсын."}, {"c": 40, "ar": "((يَقُولُ: ((آمَنْتُ بِاللَّهِ وَرُسُلِهِ)).", "n": 1, "a": "134", "ru": "Пусть скажет: «Я уверовал в Аллаха и Его посланников».", "kk": "«Аллаһқа және Оның елшілеріне иман келтірдім», – деп айтсын."}, {"c": 40, "ar": "((يَقْرَأُ قَوْلَهُ تَعَالَى: ﴿هُوَ الْأوَّلُ وَالْآخِرُ وَالظّاهِرُ وَالْباطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾)).", "n": 1, "a": "135", "ru": "Пусть прочтёт слова Всевышнего: «Он — Первый и Последний, Явный и Скрытый, и Он знает о всякой вещи».", "kk": "Аллаһ Тағаланың мына сөзін оқысын: «Ол — Әуелгі әрі Соңғы, Айқын әрі Жасырын, және Ол — барлық нәрсені Білуші»."}, {"c": 41, "ar": "((اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكِ عَمَّنْ سِوَاكَ)).", "n": 1, "a": "136", "ru": "О Аллах, огради меня дозволенным Тобою от запретного Тобою и Своей щедростью избавь меня от нужды во всех, кроме Тебя.", "kk": "Уа, Аллаһ! Халал еткеніңмен мені харам еткеніңнен жеткілікті ет және Өз кеңшілігіңмен мені Сенен өзгелерге мұқтаж етпе."}, {"c": 41, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).", "n": 1, "a": "137", "ru": "О Аллах, поистине, я прибегаю к Тебе от тревоги и печали, от бессилия и лени, от скупости и трусости, от бремени долга и от притеснения людей.", "kk": "Уа, Аллаһ! Шынымен, мен Саған уайым мен қайғыдан, дәрменсіздік пен жалқаулықтан, сараңдық пен қорқақтықтан, қарыздың ауыртпалығынан және адамдардың үстемдік етуінен пана сұраймын."}, {"c": 42, "ar": "((أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ، وَاتْفُلْ عَلَى يَسَارِكَ (ثلاثاً))).", "n": 1, "a": "138", "ru": "«Прибегаю к Аллаху от шайтана, побиваемого камнями», — и слегка сплюнь влево (трижды).", "kk": "«Қуылған шайтаннан Аллаһқа сыйынамын», – де де, сол жағыңа сәл түкір (үш рет)."}, {"c": 43, "ar": "((اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً)).", "n": 1, "a": "139", "ru": "О Аллах, нет ничего лёгкого, кроме того, что Ты сделал лёгким, а трудное Ты, если пожелаешь, делаешь лёгким.", "kk": "Уа, Аллаһ! Сен жеңіл еткен нәрседен басқа ешбір жеңіл нәрсе жоқ. Ал Сен қаласаң, қиынды да жеңіл етесің."}, {"c": 44, "ar": "((مَا مِنْ عَبْدٍ يُذنِبُ ذَنْباً فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ)).", "n": 1, "a": "140", "ru": "Нет такого раба, который совершил бы грех, затем как следует совершил очищение, затем встал и помолился два раката, а затем попросил прощения у Аллаха, — чтобы Аллах не простил его.", "kk": "Күнә жасаған қай құл болсын, жақсылап дәрет алып, содан кейін тұрып екі ракағат намаз оқыса, сосын Аллаһтан кешірім сұраса, Аллаһ оны міндетті түрде кешіреді."}, {"c": 45, "ar": "((الْاسْتِعَاذَةُ بِاللَّهِ مِنْهُ)).", "n": 1, "a": "141", "ru": "Просить у Аллаха защиты от него.", "kk": "Одан Аллаһқа сыйыну."}, {"c": 45, "ar": "((الْأَذَانُ)).", "n": 1, "a": "142", "ru": "Азан.", "kk": "Азан."}, {"c": 45, "ar": "((الْأَذْكَارُ وَقِرَاءَةُ الْقُرْآنِ)).", "n": 1, "a": "143", "ru": "Поминания Аллаха и чтение Корана.", "kk": "Зікірлер және Құран оқу."}, {"c": 46, "ar": "((قَدَرُ اللَّهُ وَمَا شَاءَ فَعَلَ)).", "n": 1, "a": "144", "ru": "Это предопределение Аллаха, и что Он пожелал, то и сделал.", "kk": "Бұл — Аллаһтың тағдыры, Ол қалағанын істеді."}, {"c": 47, "ar": "((بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ)). وَيَرُدُّ عَلَيْهِ الْمُهَــــــنَّأُ فَيَقُولُ: ((بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ)).", "n": 1, "a": "145", "ru": "«Да благословит тебя Аллах в том, что даровано тебе, и да будешь ты благодарен Дарующему; да достигнет он зрелости, и да будет тебе дарована его почтительность». А тот, кого поздравляют, отвечает: «Да благословит Аллах тебя и да ниспошлёт Он тебе благодать, да воздаст тебе Аллах благом, да дарует тебе Аллах подобного ему и да умножит Он твою награду».", "kk": "«Аллаһ саған сыйға берілгенге береке берсін, Сыйлаушыға шүкір ет, ол ер жетсін және оның саған деген ізгілігі нәсіп болсын». Ал құттықталушы оған: «Аллаһ саған береке берсін және үстіңе береке төксін, Аллаһ сені жақсылықпен марапаттасын, Аллаһ саған да сондайды нәсіп етсін және сауабыңды молайтсын», – деп жауап береді."}, {"c": 48, "ar": "كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُعَوِّذُ الحَسَنَ وَالحُسَينَ رضي الله عنهما ((أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ)).", "n": 1, "a": "146", "ru": "Посланник Аллаха ﷺ просил защиты для аль-Хасана и аль-Хусейна (да будет доволен ими Аллах) [такими словами]: «Прошу для вас защиты у совершенных слов Аллаха от всякого шайтана и ядовитой твари и от всякого дурного глаза».", "kk": "Аллаһтың елшісі ﷺ Хасан мен Хұсайынды (Аллаһ екеуінен разы болсын) былай деп пана тілеп қорғайтын: «Сендерді Аллаһтың кемел сөздерінің панасына әрбір шайтаннан, улы жәндіктен және әрбір зақым келтіретін көзден сақтауға тапсырамын»."}, {"c": 49, "ar": "((لاَ بأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ)).", "n": 1, "a": "147", "ru": "Ничего страшного, (это) очищение, если пожелает Аллах.", "kk": "Оқасы жоқ, Аллаһ қаласа, (бұл) тазару."}, {"c": 49, "ar": "((أَسْأَلُ اللَّهَ الْعَظيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفيَكَ)) (سبع مرات).", "n": 7, "a": "148", "ru": "«Прошу Аллаха Великого, Господа великого Трона, исцелить тебя» (семь раз).", "kk": "«Ұлы Аршының Раббысы, Ұлы Аллаһтан сені сауықтыруын сұраймын» (жеті рет)."}, {"c": 50, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم: ((إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خِرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ، فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ)).", "n": 1, "a": "149", "ru": "Пророк ﷺ сказал: «Когда человек навещает своего брата-мусульманина, он идёт среди собранных плодов Рая, пока не сядет, а когда сядет, его окутывает милость. Если это было утром, за него молятся семьдесят тысяч ангелов до вечера, а если вечером — за него молятся семьдесят тысяч ангелов до утра».", "kk": "Пайғамбар ﷺ былай деді: «Кісі мұсылман бауырының көңілін сұрауға барса, отырғанға дейін жәннаттың терілген жемістерінің арасында жүреді, ал отырғанда оны рақым қаптап алады. Егер бұл таңертең болса, кешке дейін оған жетпіс мың періште дұға етеді, ал егер кешке болса, таңға дейін оған жетпіс мың періште дұға етеді»."}, {"c": 51, "ar": "((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى)).", "n": 1, "a": "150", "ru": "О Аллах, прости меня, помилуй меня и присоедини меня к Высшему Сообществу.", "kk": "Уа, Аллаһ! Мені кешір, маған рақым ет және мені ең жоғарғы Серіктерге қос."}, {"c": 51, "ar": "((جَعَلَ النَّبِيُّ صلى الله عليه وسلم عِنْدَ مَوْتِهِ يُدْخِلُ يَدَيْهِ فِي الْمَاءِ فَيَمْسَحُ بِهِمَا وَجْهَهُ، وَيَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ)).", "n": 1, "a": "151", "ru": "Пророк ﷺ, когда к нему пришла смерть, стал опускать руки в воду и обтирать ими лицо, говоря: «Нет божества, кроме Аллаха! Поистине, у смерти есть предсмертные муки».", "kk": "Пайғамбар ﷺ қайтыс болар сәтінде қолдарын суға салып, олармен бетін сипай бастады да: «Аллаһтан басқа құдай жоқ! Шынында, өлімнің қиналыстары бар», – деді."}, {"c": 51, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "n": 1, "a": "152", "ru": "Нет божества, кроме Аллаха, и Аллах Велик. Нет божества, кроме одного лишь Аллаха. Нет божества, кроме одного лишь Аллаха, у Которого нет сотоварища. Нет божества, кроме Аллаха, Ему принадлежит власть и Ему хвала. Нет божества, кроме Аллаха, и нет мощи и силы, кроме как у Аллаха.", "kk": "Аллаһтан басқа құдай жоқ, Аллаһ ұлы. Жалғыз Аллаһтан басқа құдай жоқ. Жалғыз, серігі жоқ Аллаһтан басқа құдай жоқ. Аллаһтан басқа құдай жоқ, билік Соныкі және мадақ Соған тән. Аллаһтан басқа құдай жоқ, күш те, қуат та тек Аллаһ арқылы ғана."}, {"c": 52, "ar": "((مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ)).", "n": 1, "a": "ar_7esn_AlMoslem_by_Doors_053", "ru": "Тот, чьими последними словами будут «Нет божества, кроме Аллаха», войдёт в Рай.", "kk": "Кімнің соңғы сөзі «Аллаһтан басқа құдай жоқ» болса, сол жәннатқа кіреді."}, {"c": 53, "ar": "((إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً مِنْهَا)).", "n": 1, "a": "154", "ru": "Поистине, мы принадлежим Аллаху, и, поистине, к Нему мы возвращаемся. О Аллах, вознагради меня в моём несчастье и дай мне взамен лучшее, чем то, что я потерял.", "kk": "Шынында, біз Аллаһқа тиесіліміз және, шынында, Оған қайтамыз. Уа, Аллаһ! Басыма түскен мұсибат үшін маған сауап бер және оның орнына маған одан жақсырағын бер."}, {"c": 54, "ar": "((اللَّهُمَّ اغْفِرْ لِفُلاَنٍ (بِاسْمِهِ) وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ  يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ)).", "n": 1, "a": "155", "ru": "О Аллах, прости такого-то (называет его по имени), возвысь его степень среди ведомых прямым путём, будь его преемником для остающихся после него потомков, прости нас и его, о Господь миров, расширь ему его могилу и освети её для него.", "kk": "Уа, Аллаһ! Пәленшені (атын атайды) кешір, оның дәрежесін тура жолға салынғандардың арасында көтер, артында қалған ұрпағына Өзің оның орнын бас, бізді де, оны да кешір, уа, әлемдердің Раббысы! Оның қабірін кең ет және оны ол үшін нұрландыр."}, {"c": 55, "ar": "((اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، وَزَوْجَاً خَيْراً مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ [وَعَذَابِ النَّارِ])).", "n": 1, "a": "156", "ru": "О Аллах, прости его, помилуй его, даруй ему избавление, извини его, окажи почёт его пристанищу, сделай просторным место, в которое он входит, омой его водой, снегом и градом, очисти его от прегрешений, как Ты очистил белую одежду от грязи, дай ему взамен обитель лучше его обители, семью лучше его семьи и супругу лучше его супруги, введи его в Рай и защити его от мучений могилы [и мучений Огня].", "kk": "Уа, Аллаһ! Оны кешір, оған рақым ет, оған амандық бер, оның қателіктерін кешіріп жібер, оның қонатын орнын құрметті ет, кіретін жерін кең ет, оны сумен, қармен және бұршақпен жу, ақ киімді кірден тазартқаның секілді оны күнәлардан тазарт, оған мекенінен жақсырақ мекен, отбасынан жақсырақ отбасы және жұбайынан жақсырақ жұбай бер, оны жәннатқа кіргіз және оны қабір азабынан [әрі тозақ азабынан] сақта."}, {"c": 55, "ar": "((اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلاَمِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِيمَانِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ)).", "n": 1, "a": "157", "ru": "О Аллах, прости нашим живым и нашим умершим, присутствующим из нас и отсутствующим, малым из нас и большим, нашим мужчинам и нашим женщинам. О Аллах, того из нас, кому Ты даруешь жизнь, сохрани в живых в Исламе, а того из нас, кого Ты упокоишь, упокой в вере. О Аллах, не лиши нас награды за него и не введи нас в заблуждение после него.", "kk": "Уа, Аллаһ! Тірімізді де, өлімізді де, осында барымызды да, жоғымызды да, кішімізді де, үлкенімізді де, ерімізді де, әйелімізді де кешір. Уа, Аллаһ! Арамыздан кімге өмір берсең, оны Исламда өмір сүргіз, ал арамыздан кімнің жанын алсаң, оның жанын иманда ал. Уа, Аллаһ! Бізді оның сауабынан құр қалдырма және одан кейін бізді адастырма."}, {"c": 55, "ar": "((اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ، وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الغَفُورُ الرَّحيمُ)).", "n": 1, "a": "158", "ru": "О Аллах, поистине, такой-то, сын такого-то, находится под Твоим покровительством и под защитой Твоего соседства, так огради же его от испытания могилы и от мучений Огня. Ты — Достойный верности и истины, так прости же его и помилуй его, поистине, Ты — Прощающий, Милосердный.", "kk": "Уа, Аллаһ! Шынында, пәленшенің ұлы пәленше Сенің кепілдігіңде және Сенің панаңның жібінде. Ендеше оны қабір сынағынан және тозақ азабынан сақта. Сен — уәдеге адалдық пен ақиқаттың иесісің. Оны кешір және оған рақым ет. Шынында, Сен — Кешірімдісің, Мейірімдісің."}, {"c": 55, "ar": "((اللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِناً فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئاً فَتَجَاوَزْ عَنْهُ)).", "n": 1, "a": "159", "ru": "О Аллах, Твой раб, сын Твоей рабыни, нуждается в Твоей милости, а Ты не нуждаешься в его наказании. Если он творил добро, то приумножь его добрые дела, а если творил зло, то прости его.", "kk": "Уа, Аллаһ! Сенің құлың, күңіңнің ұлы Сенің рақымыңа мұқтаж болды, ал Сен оны азаптаудан беймұқтажсың. Егер ол жақсылық жасаушы болса, оның жақсылықтарын арттыр, ал егер жамандық жасаушы болса, оны кешіп жібер."}, {"c": 56, "ar": "((اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ)) وإن قال: ((اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ، وَشَفِيعاً مُجَاباً، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ)) إن قال ذلك فَحَسَنٌ.", "n": 1, "a": "160", "ru": "«О Аллах, защити его от мучений могилы». А если он скажет: «О Аллах, сделай его предшественником и сбережённым сокровищем для его родителей и заступником, чьё заступничество принимается. О Аллах, утяжели благодаря ему их весы и приумножь благодаря ему их награду, присоедини его к праведным из верующих, помести его под опеку Ибрахима, защити его Своей милостью от мучений Ада и дай ему взамен обитель лучше его обители и семью лучше его семьи. О Аллах, прости нашим предкам, нашим детям, ушедшим прежде нас, и тем, кто опередил нас в вере», — то, если он скажет это, это хорошо.", "kk": "«Уа, Аллаһ! Оны қабір азабынан сақта». Ал егер: «Уа, Аллаһ! Оны ата-анасы үшін алдын ала барушы әрі сақталған қор ет, әрі шапағаты қабыл болатын шапағатшы ет. Уа, Аллаһ! Ол арқылы екеуінің таразыларын ауырлат және ол арқылы екеуінің сауаптарын ұлғайт, оны ізгі мүміндерге қос, оны Ибраһимнің қамқорлығына бер, Өз рақымыңмен оны тозақ азабынан сақта, оған мекенінен жақсырақ мекен және отбасынан жақсырақ отбасы бер. Уа, Аллаһ! Ата-бабаларымызды, алдымызда кеткен перзенттерімізді және бізден бұрын иман келтіргендерді кешір», – десе, мұны айтса, жақсы болады."}, {"c": 56, "ar": "((اللَّهُمَّ اجْعَلْهُ لَنَا فَرَطاً، وَسَلَفاً، وَأَجْراً)).", "n": 1, "a": "161", "ru": "О Аллах, сделай его для нас предшественником, предтечей и наградой.", "kk": "Уа, Аллаһ! Оны біз үшін алдын ала барушы, бізден бұрын кеткен (қор) және сауап ет."}, {"c": 57, "ar": "((إِنَّ للَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمَّى... فَلْتَصْبِرْ وَلْتَحْتَسِبْ)). وَإِنْ قَالَ: ((أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ)) فَحَسَنٌ.", "n": 1, "a": "162", "ru": "«Поистине, Аллаху принадлежит то, что Он взял, и Ему принадлежит то, что Он дал, и у Него всему свой назначенный срок… Так пусть же терпит и надеется на награду Аллаха». А если он скажет: «Да увеличит Аллах твою награду, да дарует тебе прекрасное утешение и да простит твоего умершего», — то это хорошо.", "kk": "«Шынында, алғаны да Аллаһтікі, бергені де Соныкі, Оның алдында әрбір нәрсенің белгіленген мерзімі бар... Ендеше сабыр етсін және сауабын Аллаһтан күтсін». Ал егер: «Аллаһ сауабыңды ұлғайтсын, саған көркем жұбаныш берсін және марқұмыңды кешірсін», – десе, бұл жақсы."}, {"c": 58, "ar": "((بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ)).", "n": 1, "a": "163", "ru": "С именем Аллаха и согласно Сунне Посланника Аллаха.", "kk": "Аллаһтың атымен және Аллаһтың елшісінің сүннеті бойынша."}, {"c": 59, "ar": "((اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ثَبِّتْهُ)).", "n": 1, "a": "164", "ru": "О Аллах, прости его! О Аллах, укрепи его!", "kk": "Уа, Аллаһ, оны кешір! Уа, Аллаһ, оны берік ет!"}, {"c": 60, "ar": "((السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ، مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لاَحِقُونَ، [وَيَرْحَمُ اللَّهُ الْمُسْتَقدِمِينَ مِنَّا وَالْمُسْتأْخِرِينَ] أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ)).", "n": 1, "a": "165", "ru": "Мир вам, обитатели этих жилищ из числа верующих и мусульман! И мы, если пожелает Аллах, присоединимся к вам. [Да помилует Аллах тех из нас, кто ушёл раньше, и тех, кто уйдёт позже.] Прошу Аллаха о благополучии для нас и для вас.", "kk": "Уа, мүміндер мен мұсылмандардан болған мекен иелері, сендерге сәлем болсын! Біз де, Аллаһ қаласа, сендерге қосыламыз. [Аллаһ арамыздан бұрын кеткендерге де, кейін қалғандарға да рақым етсін.] Аллаһтан өзімізге де, сендерге де амандық сұраймын."}, {"c": 61, "ar": "((اللَّهُمَّ إِنِّي أَسْــــــأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا)).", "n": 1, "a": "166", "ru": "О Аллах, поистине, я прошу Тебя о его благе и прибегаю к Тебе от его зла.", "kk": "Уа, Аллаһ! Шынымен, мен Сенен оның жақсылығын сұраймын және оның жамандығынан Саған сыйынамын."}, {"c": 61, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ)).", "n": 1, "a": "167", "ru": "О Аллах, поистине, я прошу Тебя о его благе, о благе того, что в нём, и о благе того, с чем он послан, и прибегаю к Тебе от его зла, от зла того, что в нём, и от зла того, с чем он послан.", "kk": "Уа, Аллаһ! Шынымен, мен Сенен оның жақсылығын, ондағы нәрсенің жақсылығын және ол жіберілген нәрсенің жақсылығын сұраймын, әрі оның жамандығынан, ондағы нәрсенің жамандығынан және ол жіберілген нәрсенің жамандығынан Саған сыйынамын."}, {"c": 62, "ar": "((سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلاَئِكةُ مِنْ خِيفَتِهِ)).", "n": 1, "a": "168", "ru": "Пречист Тот, Кого прославляет хвалой гром, а также ангелы — из страха перед Ним.", "kk": "Күн күркіреуі Оны мадақпен пәктейтін, ал періштелер Одан қорыққаннан пәктейтін Зат пәк."}, {"c": 63, "ar": "((اللَّهُمَّ اسْقِنَا غَيْثاً مُغِيثاً مَرِيئاً مَرِيعاً، نَافِعاً غَيْرَ ضَارٍّ، عَاجِلاً غَيْرَ آجِلٍ)).", "n": 1, "a": "169", "ru": "О Аллах, напои нас дождём спасительным, благотворным, плодородным, полезным, а не вредным, скорым, а не отсроченным.", "kk": "Уа, Аллаһ! Бізге құтқарушы, игілікті, құнарлы, зиянды емес — пайдалы, кешіккен емес — жедел жаңбырмен суар."}, {"c": 63, "ar": "((اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا)).", "n": 1, "a": "170", "ru": "О Аллах, помоги нам дождём! О Аллах, помоги нам дождём! О Аллах, помоги нам дождём!", "kk": "Уа, Аллаһ, бізге жаңбыр жаудыр! Уа, Аллаһ, бізге жаңбыр жаудыр! Уа, Аллаһ, бізге жаңбыр жаудыр!"}, {"c": 63, "ar": "((اللَّهُمَّ اسْقِ عِبَادَكَ، وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِي بَلَدَكَ الْمَيِّتَ)).", "n": 1, "a": "171", "ru": "О Аллах, напои Своих рабов и Свой скот, распространи Свою милость и оживи Свою мёртвую землю.", "kk": "Уа, Аллаһ! Құлдарыңды және малдарыңды суар, рақымыңды тарат және өлі жеріңді тірілт."}, {"c": 64, "ar": "((اللَّهُمَّ صَيِّباً نَافِعاً)).", "n": 1, "a": "172", "ru": "О Аллах, (пусть это будет) дождь обильный и полезный!", "kk": "Уа, Аллаһ! (Бұл) мол әрі пайдалы жаңбыр болсын!"}, {"c": 65, "ar": "((مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ)).", "n": 1, "a": "173", "ru": "Нам ниспослан дождь по щедрости Аллаха и Его милости.", "kk": "Бізге Аллаһтың кеңшілігімен және Оның рақымымен жаңбыр жауды."}, {"c": 66, "ar": "((اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ)).", "n": 1, "a": "174", "ru": "О Аллах, вокруг нас, а не на нас! О Аллах, на холмы и возвышенности, на дно долин и на места, где растут деревья!", "kk": "Уа, Аллаһ! Айналамызға жаудыр, үстімізге емес! Уа, Аллаһ! Төбелер мен адырларға, аңғарлардың табанына және ағаш өсетін жерлерге жаудыр!"}, {"c": 67, "ar": "((اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ، وَالسَّلاَمَةِ وَالْإِسْلاَمِ، وَالتَّوْفِيقِ لِمَا تُحِبُّ رَبَّنَا وَتَرْضَى، رَبُّنَا وَرَبُّكَ اللَّهُ)).", "n": 1, "a": "175", "ru": "Аллах Велик! О Аллах, дай ему (новому месяцу) взойти над нами с безопасностью и верой, с благополучием и Исламом и с содействием в том, что Ты любишь и чем доволен, Господь наш. Наш Господь и твой Господь — Аллах.", "kk": "Аллаһ ұлы! Уа, Аллаһ! Оны (жаңа айды) бізге амандық пен иманмен, есендік пен Исламмен және Өзің жақсы көретін әрі разы болатын нәрсеге муаффақ етумен туғыз, уа, Раббымыз! Біздің Раббымыз да, сенің Раббың да — Аллаһ."}, {"c": 68, "ar": "((ذَهَبَ الظَّمَأُ وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ)).", "n": 1, "a": "176", "ru": "Ушла жажда, увлажнились жилы, и утвердилась награда, если пожелает Аллах.", "kk": "Шөл басылды, тамырлар суланды және, Аллаһ қаласа, сауап бекіді."}, {"c": 68, "ar": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ أَنْ تَغْفِرَ لِي)).", "n": 1, "a": "177", "ru": "О Аллах, поистине, я прошу Тебя Твоей милостью, которая объемлет всё сущее, простить меня.", "kk": "Уа, Аллаһ! Шынымен, мен Сенен барлық нәрсені қамтыған рақымың арқылы мені кешіруіңді сұраймын."}, {"c": 69, "ar": "((إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً فَلْيَقُلْ بِسْمِ اللَّهِ، فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ بسمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ)).", "n": 1, "a": "178", "ru": "«Когда кто-нибудь из вас ест пищу, пусть скажет: «С именем Аллаха». А если забудет (сказать это) в начале, пусть скажет: «С именем Аллаха в начале её и в конце её»».", "kk": "«Сендердің біреулерің тамақ жегенде: «Аллаһтың атымен (Бисмиллаһ)», – деп айтсын. Ал егер басында (айтуды) ұмытып кетсе: «Басында да, соңында да Аллаһтың атымен», – деп айтсын»."}, {"c": 69, "ar": "((مَنْ أَطْعَمَهُ اللَّهُ الطَّعَامَ فَلْيَقُلْ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ، وَمَنْ سَقَاهُ اللَّهُ لَبَناً فَلْيَقُلْ اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ)).", "n": 1, "a": "179", "ru": "«Кого Аллах накормил пищей, пусть скажет: «О Аллах, благослови нас в ней и накорми нас тем, что лучше неё». А кого Аллах напоил молоком, пусть скажет: «О Аллах, благослови нас в нём и дай нам его ещё больше»».", "kk": "«Кімді Аллаһ тамақпен тамақтандырса, ол: «Уа, Аллаһ, бізге оны берекелі ет және бізді одан да жақсысымен тамақтандыр», – деп айтсын. Ал кімді Аллаһ сүтпен сусындатса, ол: «Уа, Аллаһ, бізге оны берекелі ет және оны бізге көбейте түс», – деп айтсын»."}, {"c": 70, "ar": "((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ)).", "n": 1, "a": "180", "ru": "«Хвала Аллаху, Который накормил меня этим и наделил меня этим без какой-либо силы и мощи с моей стороны».", "kk": "«Мені осымен тамақтандырған және маған мұны менің ешбір әл-қуатымсыз ризық етіп берген Аллаһқа мадақ»."}, {"c": 70, "ar": "((الْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ، غَيْرَ [مَكْفِيٍّ وَلاَ ] مُوَدَّعٍ، وَلاَ مُسْتَغْنَىً عَنْهُ رَبَّنَا)).", "n": 1, "a": "181", "ru": "«Хвала Аллаху – хвала обильная, благая и благословенная, [хвала, которой никогда не будет достаточно,] с которой не прощаются навсегда и без которой не обойтись, о Господь наш!»", "kk": "«Аллаһқа мадақ – көп, пәк әрі берекелі мадақ; [ешқашан жеткілікті болмайтын,] біржола қоштасылмайтын және онсыз етуге болмайтын мадақ, уа, Раббымыз!»"}, {"c": 71, "ar": "((اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ)).", "n": 1, "a": "182", "ru": "«О Аллах, благослови их в том, чем Ты их наделил, прости их и помилуй их».", "kk": "«Уа, Аллаһ, оларға Өзің берген ризықты берекелі ет, оларды кешір және оларға рақым ет»."}, {"c": 72, "ar": "((اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي)).", "n": 1, "a": "183", "ru": "«О Аллах, накорми того, кто накормил меня, и напои того, кто напоил меня».", "kk": "«Уа, Аллаһ, мені тамақтандырған адамды Сен тамақтандыр, мені сусындатқан адамды Сен сусындат»."}, {"c": 73, "ar": "((أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ)).", "n": 1, "a": "184", "ru": "«Пусть разговляются у вас постящиеся, пусть едят вашу пищу благочестивые, и пусть ангелы молятся за вас».", "kk": "«Сендердің үйлеріңде ораза ұстаушылар ауыз ашсын, тамақтарыңды ізгі жандар жесін және сендерге періштелер дұға етсін»."}, {"c": 74, "ar": "((إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً فَلْيَطْعَمْ)) ، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.", "n": 1, "a": "185", "ru": "«Если кого-нибудь из вас пригласят, пусть примет приглашение. И если он постится, пусть помолится, а если не постится – пусть поест». А смысл слов «пусть помолится» – то есть пусть обратится с мольбой (дуа).", "kk": "«Сендердің біреулерің (тамаққа) шақырылса, шақыруды қабыл алсын. Егер ораза ұстап жүрсе, намаз оқысын (дұға жасасын), ал ораза болмаса, тамақ жесін». «Намаз оқысын» деген сөздің мағынасы – дұға жасасын дегені."}, {"c": 75, "ar": "((إِنِّي صَائِمٌ، إِنِّي صَائِمٌ)).", "n": 1, "a": "186", "ru": "«Поистине, я пощусь, поистине, я пощусь».", "kk": "«Мен шынында оразадамын, мен шынында оразадамын»."}, {"c": 76, "ar": "((اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا)).", "n": 1, "a": "187", "ru": "«О Аллах, благослови нас в наших плодах, благослови нас в нашем городе, благослови нас в нашем саа и благослови нас в нашем мудде».", "kk": "«Уа, Аллаһ, бізге жемістерімізді берекелі ет, бізге қаламызды берекелі ет, бізге сағымызды берекелі ет және бізге муддымызды берекелі ет»."}, {"c": 77, "ar": "((إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ الْحَمْدُ لِلَّهِ، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ اللَّهُ، فَإِذَا قَالَ لَهُ: يَرحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).", "n": 1, "a": "188", "ru": "«Когда кто-нибудь из вас чихнёт, пусть скажет: «Хвала Аллаху», а его брат или товарищ пусть скажет ему: «Да помилует тебя Аллах». А когда тот скажет ему: «Да помилует тебя Аллах», пусть (чихнувший) скажет: «Да наставит вас Аллах на прямой путь и да приведёт Он в порядок ваши дела»».", "kk": "«Сендердің біреулерің түшкірсе: «Аллаһқа мадақ (Әлхамдулиллаһ)», – десін, ал оның бауыры немесе серігі оған: «Аллаһ саған рақым етсін», – десін. Ал ол оған: «Аллаһ саған рақым етсін», – деген кезде, (түшкірген адам): «Аллаһ сендерді тура жолға салсын және істеріңді түзетсін», – десін»."}, {"c": 78, "ar": "((يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).", "n": 1, "a": "189", "ru": "«Да наставит вас Аллах на прямой путь и да приведёт Он в порядок ваши дела».", "kk": "«Аллаһ сендерді тура жолға салсын және істеріңді түзетсін»."}, {"c": 79, "ar": "((بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ)).", "n": 1, "a": "190", "ru": "«Да благословит тебя Аллах, да ниспошлёт Он тебе благословение и да соединит Он вас обоих во благе».", "kk": "«Аллаһ саған береке берсін, саған берекесін түсірсін және екеуіңді игілікте қосып, табыстырсын»."}, {"c": 80, "ar": "إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ)).", "n": 1, "a": "191", "ru": "Когда кто-нибудь из вас женится на женщине или купит слугу, пусть скажет: «О Аллах, поистине, я прошу Тебя о её благе и о благе того, к чему Ты её предрасположил, и прибегаю к Тебе от её зла и от зла того, к чему Ты её предрасположил. А если он купит верблюда, пусть возьмётся за вершину его горба и скажет то же самое».", "kk": "Сендердің біреулерің бір әйелге үйленсе немесе қызметші сатып алса, былай десін: «Уа, Аллаһ, мен Сенен оның игілігін және Сен оны қандай болмыспен жаратсаң, соның игілігін сұраймын, әрі оның жамандығынан және Сен оны қандай болмыспен жаратсаң, соның жамандығынан Өзіңе сыйынамын. Ал егер түйе сатып алса, оның өркешінің ұшынан ұстап, дәл осыны айтсын»."}, {"c": 81, "ar": "((بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا)).", "n": 1, "a": "192", "ru": "«С именем Аллаха. О Аллах, удали от нас шайтана и удали шайтана от того, чем Ты нас наделишь».", "kk": "«Аллаһтың атымен. Уа, Аллаһ, бізді шайтаннан аулақ ет және бізге беретін нәрсеңнен шайтанды аулақ ет»."}, {"c": 82, "ar": "((أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ)).", "n": 1, "a": "193", "ru": "«Прибегаю к Аллаху от шайтана, побиваемого камнями».", "kk": "«Қуылған шайтаннан Аллаһқа сыйынамын»."}, {"c": 83, "ar": "((الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلاً)).", "n": 1, "a": "194", "ru": "«Хвала Аллаху, Который избавил меня от того, чем Он испытал тебя, и дал мне явное превосходство над многими из тех, кого Он сотворил».", "kk": "«Сені сынаған нәрседен мені аман сақтаған және мені Өзі жаратқандардың көбінен анағұрлым артық еткен Аллаһқа мадақ»."}, {"c": 84, "ar": "((عَنِ ابْنِ عُمَرَ رضي الله عنه قَاَلَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فِي الْمَجْلِسِ الوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: ((رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ)).", "n": 100, "a": "195", "ru": "«Передают от Ибн Умара (да будет доволен им Аллах), что он сказал: «На одном собрании за Посланником Аллаха ﷺ насчитывали сто раз, прежде чем он вставал: «Господи, прости меня и прими моё покаяние, поистине, Ты – Принимающий покаяние, Прощающий»».", "kk": "«Ибн Ұмардан (Аллаһ оған разы болсын) жеткен, ол былай деді: «Аллаһтың елшісі ﷺ бір мәжілістің өзінде орнынан тұрмай тұрып жүз рет: «Раббым, мені кешір және тәубемді қабыл ет, шын мәнінде Сен – Тәубені қабыл етуші, Кешірімдісің», – дегенін санайтын едік»»."}, {"c": 85, "ar": "((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)).", "n": 1, "a": "196", "ru": "«Пречист Ты, о Аллах, и хвала Тебе. Свидетельствую, что нет божества, кроме Тебя. Прошу у Тебя прощения и каюсь перед Тобой».", "kk": "«Уа, Аллаһ, Сен пәксің және Саған мадақ. Сенен басқа құдай жоқ екеніне куәлік беремін. Сенен кешірім сұраймын және Саған тәубе етемін»."}, {"c": 86, "ar": "((وَلَكَ)).", "n": 1, "a": "197", "ru": "«И тебе».", "kk": "«Саған да»."}, {"c": 87, "ar": "((جَزَاكَ اللَّهُ خَيْراً)).", "n": 1, "a": "198", "ru": "«Да воздаст тебе Аллах благом».", "kk": "«Аллаһ саған игілікпен қайтарсын»."}, {"c": 88, "ar": "((مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ)) ، وَالْاسْتِعَاذَةُ بِاللَّهِ مِنْ فِتْنَتِهِ عَقِبَ التَّشَهُّدِ الْأَخِيرِ مِنْ كُلِّ صَلاَةٍ.", "n": 1, "a": "199", "ru": "«Кто выучит наизусть десять аятов из начала суры «Пещера», тот будет защищён от Даджаля». А также (следует) прибегать к защите Аллаха от его смуты после последнего ташаххуда каждой молитвы.", "kk": "«Кім «Кәһф» сүресінің басындағы он аятты жатқа білсе, ол Дәжжалдан қорғалады». Сондай-ақ әрбір намаздың соңғы тәшәһһудынан кейін оның пітнесінен Аллаһқа сыйыну (керек)."}, {"c": 89, "ar": "((أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ)).", "n": 1, "a": "200", "ru": "«Да полюбит тебя Тот, ради Кого ты полюбил меня».", "kk": "«Сен мені кім үшін жақсы көрсең, Сол (Аллаһ) сені жақсы көрсін»."}, {"c": 90, "ar": "((بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ)).", "n": 1, "a": "201", "ru": "«Да благословит тебя Аллах в твоей семье и в твоём имуществе».", "kk": "«Аллаһ саған отбасыңда және мал-мүлкіңде береке берсін»."}, {"c": 91, "ar": "((بارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالأَدَاءُ)).", "n": 1, "a": "202", "ru": "«Да благословит тебя Аллах в твоей семье и в твоём имуществе. Поистине, воздаяние за заём – это благодарность и возврат (долга)».", "kk": "«Аллаһ саған отбасыңда және мал-мүлкіңде береке берсін. Шын мәнінде, қарыздың қайтарымы – алғыс айту және оны өтеу»."}, {"c": 92, "ar": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ أَعْلَمُ)).", "n": 1, "a": "203", "ru": "«О Аллах, поистине, я прибегаю к Тебе от того, чтобы сознательно придать Тебе сотоварища, и прошу у Тебя прощения за то, чего я не знаю».", "kk": "«Уа, Аллаһ, біле тұра Саған серік қосудан Өзіңе сыйынамын және білмей істегенім үшін Сенен кешірім сұраймын»."}, {"c": 93, "ar": "((وَفِيكَ بَارَكَ اللَّهُ)).", "n": 1, "a": "204", "ru": "«И тебя да благословит Аллах».", "kk": "«Аллаһ саған да береке берсін»."}, {"c": 94, "ar": "((اللَّهُمَّ لاَ طَيْرَ إِلاَّ طَيْرُكَ، وَلاَ خَيْرَ إِلاَّ خَيْرُكَ، وَلاَ إِلَهَ غَيْرُكَ)).", "n": 1, "a": "205", "ru": "«О Аллах, нет приметы, кроме Твоей приметы, нет блага, кроме Твоего блага, и нет божества, кроме Тебя».", "kk": "«Уа, Аллаһ, Сенің белгіңнен басқа ырым-белгі жоқ, Сенің игілігіңнен басқа игілік жоқ және Сенен басқа құдай жоқ»."}, {"c": 95, "ar": "((بِسْمِ اللَّهِ، وَالْحَمْدُ للَّهِ ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾، ((الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي؛ فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ)).", "n": 1, "a": "206", "ru": "«С именем Аллаха, и хвала Аллаху. «Пречист Тот, Кто подчинил нам это, а сами мы не были бы способны с этим совладать, и, поистине, к Господу нашему мы непременно возвратимся». Хвала Аллаху, хвала Аллаху, хвала Аллаху. Аллах Велик, Аллах Велик, Аллах Велик. Пречист Ты, о Аллах! Поистине, я поступил несправедливо по отношению к самому себе, прости же меня, ведь никто не прощает грехи, кроме Тебя».", "kk": "«Аллаһтың атымен, Аллаһқа мадақ. «Мұны бізге бағындырған (Аллаһ) пәк, әйтпесе біз оны игере алмас едік. Және, сөз жоқ, біз Раббымызға қайтушымыз». Аллаһқа мадақ, Аллаһқа мадақ, Аллаһқа мадақ. Аллаһ ұлы, Аллаһ ұлы, Аллаһ ұлы. Уа, Аллаһ, Сен пәксің! Мен өзіме-өзім зұлымдық жасадым, мені кешіре гөр, өйткені күнәларды Сенен басқа ешкім кешірмейді»."}, {"c": 96, "ar": "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾ ((اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَليفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ))، وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: ((آيِبُونَ، تائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ)).", "n": 1, "a": "207", "ru": "Аллах Велик, Аллах Велик, Аллах Велик. «Пречист Тот, Кто подчинил нам это, а сами мы не были бы способны с этим совладать, и, поистине, к Господу нашему мы непременно возвратимся». «О Аллах, мы просим Тебя в этой нашей поездке о благочестии и богобоязненности и о таких делах, которыми Ты будешь доволен. О Аллах, облегчи нам эту нашу поездку и сократи для нас её расстояние. О Аллах, Ты – Спутник в пути и Тот, Кто остаётся Преемником в семье. О Аллах, поистине, я прибегаю к Тебе от тягот пути, от удручающего зрелища и от дурного возвращения к имуществу и семье». А возвратившись, он произносил эти слова и добавлял к ним: «Мы возвращаемся, каемся, поклоняемся и Господа нашего восхваляем».", "kk": "Аллаһ ұлы, Аллаһ ұлы, Аллаһ ұлы. «Мұны бізге бағындырған (Аллаһ) пәк, әйтпесе біз оны игере алмас едік. Және, сөз жоқ, біз Раббымызға қайтушымыз». «Уа, Аллаһ, біз Сенен осы сапарымызда ізгілік пен тақуалықты және Өзің разы болатын амалды сұраймыз. Уа, Аллаһ, осы сапарымызды бізге жеңіл ет және оның алыс жолын бізге қысқарт. Уа, Аллаһ, Сен – сапардағы Серіксің және отбасындағы Орынбасарсың. Уа, Аллаһ, мен сапардың машақатынан, көңілсіз көріністен және мал-мүлік пен отбасына жаман оралудан Өзіңе сыйынамын». Ал қайтып оралғанда, осы сөздерді айтып, оларға мынаны қосатын: «Біз оралушымыз, тәубе етушіміз, құлшылық етушіміз, Раббымызға мадақ айтушымыз»."}, {"c": 97, "ar": "((اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّياطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ، وَخَيْرَ أَهْلِهَا، وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ أَهْلِهَا، وَشَرِّ مَا فِيهَا)).", "n": 1, "a": "208", "ru": "«О Аллах, Господь семи небес и того, что они осеняют, Господь семи земель и того, что они несут на себе, Господь шайтанов и тех, кого они ввели в заблуждение, Господь ветров и того, что они развеивают! Я прошу Тебя о благе этого селения, о благе его жителей и о благе того, что в нём, и прибегаю к Тебе от его зла, от зла его жителей и от зла того, что в нём».", "kk": "«Уа, Аллаһ, жеті көктің және олар көлеңкелеген нәрселердің Раббысы, жеті жердің және олар көтеріп тұрған нәрселердің Раббысы, шайтандардың және олар адастырғандардың Раббысы, желдердің және олар ұшырып әкеткен нәрселердің Раббысы! Сенен осы елді мекеннің игілігін, оның тұрғындарының игілігін және ондағы нәрселердің игілігін сұраймын, әрі оның жамандығынан, оның тұрғындарының жамандығынан және ондағы нәрселердің жамандығынан Өзіңе сыйынамын»."}, {"c": 98, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لاِ يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).", "n": 1, "a": "209", "ru": "«Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, и Ему хвала. Он дарует жизнь и умерщвляет, и Он – Живой, Который не умирает. В Его руке благо, и Он над всякой вещью властен».", "kk": "«Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ. Билік Соныкі және мадақ Соған тән. Ол тірілтеді әрі өлтіреді, Ол – өлмейтін Тірі. Игілік Оның қолында және Ол – барлық нәрсеге құдіретті»."}, {"c": 99, "ar": "((بِسْمِ اللَّهِ)).", "n": 1, "a": "210", "ru": "«С именем Аллаха».", "kk": "«Аллаһтың атымен (Бисмиллаһ)»."}, {"c": 100, "ar": "((أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لاَ تَضِيعُ وَدَائِعُهُ)).", "n": 1, "a": "211", "ru": "«Вверяю вас Аллаху, у Которого не пропадает то, что Ему вверено».", "kk": "«Сендерді аманаттары жоғалмайтын Аллаһқа аманат етемін»."}, {"c": 101, "ar": "(( أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ)).", "n": 1, "a": "212", "ru": "«Вверяю Аллаху твою религию, твою верность (доверенное тебе) и завершение твоих дел».", "kk": "«Сенің дініңді, аманатыңды және амалдарыңның соңын Аллаһқа аманат етемін»."}, {"c": 101, "ar": "((زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الخَيْرَ حَيْثُ ما كُنْتَ)).", "n": 1, "a": "213", "ru": "«Да снабдит тебя Аллах богобоязненностью (как припасом в дорогу), да простит Он твой грех и да облегчит Он тебе благо, где бы ты ни был».", "kk": "«Аллаһ саған тақуалықты азық етсін, күнәңді кешірсін және қайда болсаң да, саған игілікті жеңіл етсін»."}, {"c": 102, "ar": "قَالَ جَابِرٌ رضي الله عنه: ((كُنَّا إِذَا صَعَدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا)).", "n": 1, "a": "214", "ru": "Джабир (да будет доволен им Аллах) сказал: «Когда мы поднимались вверх, мы произносили «Аллах Велик», а когда спускались, произносили «Слава Аллаху»».", "kk": "Жәбир (Аллаһ оған разы болсын) былай деді: «Біз жоғары көтерілгенде «Аллаһ ұлы» дейтін едік, ал төмен түскенде «Аллаһ пәк» дейтін едік»."}, {"c": 103, "ar": "((سَمَّعَ سَامِعٌ بِحَمْدِ اللَّهِ، وَحُسْنِ بَلاَئِهِ عَلَيْنَا، رَبَّنَا صاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذاً بِاللَّهِ مِنَ النَّارِ)).", "n": 1, "a": "215", "ru": "«Пусть слышащий засвидетельствует (и передаст другим) нашу хвалу Аллаху и Его прекрасную милость к нам. Господь наш, будь нашим Спутником и окажи нам Свою милость. (Говорю это,) прибегая к Аллаху от Огня».", "kk": "«Естуші біздің Аллаһқа айтқан мадағымызға және Оның бізге берген көркем нығметіне куә болып, (оны басқаларға) жеткізсін. Раббымыз, бізге Серік бол және бізге мол рақымыңды төк. (Мұны) Аллаһтан Тозақтан пана сұрай отырып (айтамын)»."}, {"c": 104, "ar": "((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)).", "n": 1, "a": "216", "ru": "«Прибегаю к совершенным словам Аллаха от зла того, что Он сотворил».", "kk": "«Аллаһтың кемел сөздерімен Ол жаратқан нәрселердің жамандығынан пана сұраймын»."}, {"c": 105, "ar": "((يُكَبِّرُ عَلَى كُلِّ شَرَفٍ ثَلاَثَ تَكْبِيرَاتٍ ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزابَ وَحْدَهُ)).", "n": 1, "a": "217", "ru": "«На каждой возвышенности он трижды произносил «Аллах Велик», а затем говорил: «Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища. Ему принадлежит власть, и Ему хвала, и Он над всякой вещью властен. Мы возвращаемся, каемся, поклоняемся и Господа нашего восхваляем. Аллах исполнил Своё обещание, помог Своему рабу и Один разбил союзные войска»».", "kk": "«Әрбір биік жерде үш рет «Аллаһ ұлы» деп, содан кейін былай дейтін: «Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ. Билік Соныкі, мадақ Соған тән және Ол – барлық нәрсеге құдіретті. Біз оралушымыз, тәубе етушіміз, құлшылық етушіміз, Раббымызға мадақ айтушымыз. Аллаһ уәдесін орындады, құлына жәрдем берді және одақтас топтарды жалғыз Өзі жеңді»»."}, {"c": 106, "ar": "كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَتَاهُ الْأَمْرُ يَسُرُّهُ قَالَ: ((الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ)) وَإِذَا أَتَاهُ الْأَمْرُ يَكْرَهُهُ قَالَ: ((الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ)).", "n": 1, "a": "218", "ru": "Когда к Пророку ﷺ приходило что-то, что его радовало, он говорил: «Хвала Аллаху, по милости Которого завершаются благие дела». А когда к нему приходило что-то, что ему было неприятно, он говорил: «Хвала Аллаху при любом положении».", "kk": "Пайғамбарға ﷺ қуантатын бір іс келгенде: «Нығметімен ізгі істер толық орындалатын Аллаһқа мадақ», – дейтін. Ал ұнамайтын бір іс келгенде: «Әр жағдайда Аллаһқа мадақ», – дейтін."}, {"c": 107, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم: ((مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً)).", "n": 1, "a": "219", "ru": "Пророк ﷺ сказал: «Кто благословит меня один раз, того Аллах благословит за это десять раз».", "kk": "Пайғамбар ﷺ былай деді: «Кім маған бір рет салауат айтса, Аллаһ оған сол үшін он рет салауат етеді (игілік береді)»."}, {"c": 107, "ar": "وَقَالَ صلى الله عليه وسلم: ((لاَ تَجْعَلُوا قَبْرِي عِيداً وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلاَتَكُم تَبْلُغُنِي حَيْثُ كُنْتُمْ)).", "n": 1, "a": "220", "ru": "И он ﷺ сказал: «Не превращайте мою могилу в место празднеств и благословляйте меня, ибо ваше благословение достигает меня, где бы вы ни были».", "kk": "Сондай-ақ ол ﷺ былай деді: «Менің қабірімді мереке орнына айналдырмаңдар және маған салауат айтыңдар, өйткені қайда болсаңдар да, салауаттарың маған жетеді»."}, {"c": 107, "ar": "وَقَالَ صلى الله عليه وسلم: ((الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)).", "n": 1, "a": "221", "ru": "И он ﷺ сказал: «Скупец – это тот, при ком упомянули меня, а он не благословил меня».", "kk": "Сондай-ақ ол ﷺ былай деді: «Сараң – қасында мен аталғанда, маған салауат айтпаған адам»."}, {"c": 107, "ar": "وَقَالَ صلى الله عليه وسلم:((إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلاَمَ)).", "n": 1, "a": "222", "ru": "И он ﷺ сказал: «Поистине, у Аллаха есть ангелы, которые странствуют по земле и передают мне приветствие (салям) от моей общины».", "kk": "Сондай-ақ ол ﷺ былай деді: «Шын мәнінде, Аллаһтың жер бетін кезіп жүретін періштелері бар, олар маған үмбетімнің сәлемін жеткізеді»."}, {"c": 107, "ar": "وَقَالَ صلى الله عليه وسلم: ((مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلاَّ رَدَّ اللَّهُ عَلَيَّ رُوحِيَ حَتَّى أَرُدَّ عَلَيْهِ السَّلاَمَ)).", "n": 1, "a": "223", "ru": "И он ﷺ сказал: «Нет никого, кто приветствовал бы меня, без того чтобы Аллах не возвратил мне мою душу, чтобы я ответил ему на приветствие».", "kk": "Сондай-ақ ол ﷺ былай деді: «Кімде-кім маған сәлем берсе, мен оның сәлеміне жауап беруім үшін Аллаһ міндетті түрде рухымды маған қайтарады»."}, {"c": 108, "ar": "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ((لاَ تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلاَ أَدُلُّكُم عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُم، أَفْشُوا السَّلاَمَ بَيْنَكُمْ)).", "n": 1, "a": "224", "ru": "Посланник Аллаха ﷺ сказал: «Вы не войдёте в Рай, пока не уверуете, и не уверуете, пока не полюбите друг друга. Не указать ли вам на то, сделав что, вы полюбите друг друга? Распространяйте приветствие мира (салям) между собой».", "kk": "Аллаһтың елшісі ﷺ айтты: «Иман келтірмейінше, жәннатқа кірмейсіңдер, ал бір-біріңді жақсы көрмейінше, иман келтірмейсіңдер. Сендерге бір нәрсені көрсетейін бе, оны істесеңдер, бір-біріңді жақсы көресіңдер? Араларыңда сәлемді таратыңдар»."}, {"c": 108, "ar": "((ثَلاَثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلاَمِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الإِقْتَارِ)).", "n": 1, "a": "225", "ru": "«Три качества — кто соединил их в себе, тот соединил веру: справедливость со своей стороны, предложение приветствия мира (саляма) всем людям и расходование (на благое) при скудости».", "kk": "«Үш қасиет бар, кім оларды бойына жинаса, иманды жинаған болады: өз тарапыңнан әділдік таныту, барша адамға сәлем беру және тарлықта (жоқшылықта) да (игілікке) жұмсау»."}, {"c": 108, "ar": "وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أنَّ رَجُلاً سَأَلَ النَّبِيَّ صلى الله عليه وسلم أيُّ الْإِسْلاَمِ خَيْرٌ قَالَ: ((تُطْعِمُ الطَّعَامَ، وَتَقْرأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ)).", "n": 1, "a": "226", "ru": "Передаётся от Абдуллаха ибн Умара (да будет доволен Аллах ими обоими), что один человек спросил Пророка ﷺ: «Что в исламе лучше всего?» Он сказал: «Чтобы ты кормил едой и приветствовал салямом тех, кого знаешь, и тех, кого не знаешь».", "kk": "Абдуллаһ ибн Омардан (Аллаһ екеуіне де разы болсын) жеткен: бір кісі Пайғамбардан ﷺ: «Исламның қай ісі ең жақсы?» – деп сұрады. Ол: «Тамақ беруің және таныған-танымаған адамға сәлем беруің», – деді."}, {"c": 109, "ar": "((إذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ)).", "n": 1, "a": "227", "ru": "«Когда люди Писания приветствуют вас салямом, отвечайте: “И вам” (ва-‘алейкум)».", "kk": "«Кітап иелері сендерге сәлем берсе: “Сендерге де” (уа ғалайкум), – деңдер»."}, {"c": 110, "ar": "((إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ؛ فَإِنَّهَا رَأَتْ مَلَكاً وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيطَانِ؛ فَإِنَّهُ رَأَى شَيْطَاناً)).", "n": 1, "a": "228", "ru": "«Когда услышите крик петухов, просите у Аллаха Его милости (щедрот), ибо петух увидел ангела; а когда услышите рёв осла, ищите защиты у Аллаха от шайтана, ибо осёл увидел шайтана».", "kk": "«Әтештердің шақырғанын естісеңдер, Аллаһтан Оның кеңшілігін (рақымын) сұраңдар, өйткені әтеш періштені көрді; ал есектің ақырғанын естісеңдер, Аллаһқа шайтаннан пана тілеңдер, өйткені есек шайтанды көрді»."}, {"c": 111, "ar": "((إِذَا سَمِعْتُمْ نُبَاحَ الْكِلاَبِ وَنَهِيقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ مِنْهُنَّ؛ فَإِنَّهُنَّ يَرَيْنَ مَا لاَ تَرَوْنَ)).", "n": 1, "a": "229", "ru": "«Когда услышите ночью лай собак и рёв ослов, ищите защиты у Аллаха от них, ибо они видят то, чего не видите вы».", "kk": "«Түнде иттердің үргенін және есектердің ақырғанын естісеңдер, олардан Аллаһқа пана тілеңдер, өйткені олар сендер көрмейтін нәрсені көреді»."}, {"c": 112, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم: ((اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ)).", "n": 1, "a": "230", "ru": "Пророк ﷺ сказал: «О Аллах, любого верующего, которого я поругал, — сделай это для него средством приближения к Тебе в День воскресения».", "kk": "Пайғамбар ﷺ айтты: «Уа, Аллаһ, мен кез келген мүминді сөккен болсам, мұны қиямет күні оған Саған жақындататын себеп қыл»."}, {"c": 113, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم: ((إِذَا كَانَ أَحَدُكُم مَادِحاً صَاحِبَهُ لاَ مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا وَكَذَا)).", "n": 1, "a": "231", "ru": "Пророк ﷺ сказал: «Если кто-либо из вас непременно хочет похвалить своего товарища, пусть скажет: “Я считаю такого-то (таким), а Аллах — тот, Кто взыщет с него отчёт, и я никого не очищаю (не превозношу) перед Аллахом; я считаю его — если знает это — таким-то и таким-то”».", "kk": "Пайғамбар ﷺ айтты: «Егер біреулерің өз жолдасын міндетті түрде мақтайтын болса, былай десін: “Мен пәленшені (сондай) деп есептеймін, ал оның есебін алушы – Аллаһ, мен Аллаһтың алдында ешкімді ақтап (артық бағалап) айтпаймын; мен оны – егер мұны білетін болса – пәлендей, түгендей деп есептеймін”»."}, {"c": 114, "ar": "((اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ، [وَاجْعَلْنِي خَيْراً مِمَّا يَظُّنُّونَ])).", "n": 1, "a": "232", "ru": "«О Аллах, не взыщи с меня за то, что они говорят, и прости мне то, чего они не знают, [и сделай меня лучше того, что они думают]».", "kk": "«Уа, Аллаһ, олардың айтқандары үшін мені жазаға тартпа, олар білмейтін нәрселерімді кешір [және мені олардың ойлағанынан да жақсырақ қыл]»."}, {"c": 115, "ar": "((لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ)).", "n": 1, "a": "233", "ru": "«Вот я пред Тобой, о Аллах, вот я пред Тобой! Вот я пред Тобой, нет у Тебя сотоварища, вот я пред Тобой! Поистине, хвала и милость принадлежат Тебе, и власть (Тебе). Нет у Тебя сотоварища».", "kk": "«Міне, Саған келдім, уа, Аллаһ, міне, келдім! Міне, келдім, Сенің серігің жоқ, міне, келдім! Шын мәнінде, мадақ та, нығмет те Сенікі, билік те (Сенікі). Сенің серігің жоқ»."}, {"c": 116, "ar": "((طَافَ النَّبيُّ صلى الله عليه وسلم بِالْبَيْتِ عَلَى بَعِيرٍ كُلَّمَا أَتَى الرُّكْنَ أَشَارَ إِلَيْهِ بِشَيْءٍ عِنْدَهُ وَكَبَّرَ)).", "n": 1, "a": "234", "ru": "«Пророк ﷺ совершал обход вокруг Дома (Каабы) на верблюде, и всякий раз, подходя к Углу (Чёрного камня), указывал на него чем-то, что было у него в руке, и произносил такбир (“Аллах Велик”)».", "kk": "«Пайғамбар ﷺ Үйді (Қағбаны) түйе үстінде тауап етті; бұрышқа (Қара тасқа) жеткен сайын, оған қолындағы бір нәрсемен нұсқап, тәкбір айтатын (“Аллаһ ұлы” дейтін)»."}, {"c": 117, "ar": "((﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾)).", "n": 1, "a": "235", "ru": "«Господь наш, даруй нам в этом мире благо и в последней жизни благо и защити нас от мучения Огня».", "kk": "«Раббымыз, бізге осы дүниеде де игілік бер, ақыретте де игілік бер және бізді Тозақ азабынан сақта»."}, {"c": 118, "ar": "لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ)) فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: ((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ، ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ)) الْحَدِيثُ. وَفِيهِ: ((فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)).", "n": 3, "a": "236", "ru": "Когда Пророк ﷺ приблизился к ас-Сафе, он прочитал: «Поистине, ас-Сафа и аль-Марва — из обрядовых знаков Аллаха» — и сказал: «Я начинаю с того, с чего начал Аллах». И он начал с ас-Сафы и поднялся на неё, пока не увидел Дом (Каабу), повернулся лицом к кибле, провозгласил единство Аллаха и Его величие и сказал: «Нет божества, кроме Аллаха, Единого, у Которого нет сотоварища; Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен. Нет божества, кроме Аллаха, Единого; Он исполнил Своё обещание, помог Своему рабу и Один разбил союзные племена». Затем между этим он обращался с мольбой. Он произнёс подобное этому трижды (до конца хадиса). И в нём (сказано): «И на аль-Марве он сделал так же, как сделал на ас-Сафе».", "kk": "Пайғамбар ﷺ Сафаға жақындағанда: «Шын мәнінде, Сафа мен Мәруа – Аллаһтың белгілерінен», – деп оқыды да: «Аллаһ неден бастаса, мен де содан бастаймын», – деді. Сөйтіп Сафадан бастап, Үйді (Қағбаны) көргенше оған көтерілді, құбылаға бет бұрып, Аллаһты бір деп танып, Оны ұлықтады да, былай деді: «Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ; билік Онікі, мадақ Оған тән және Ол – барлық нәрсеге құдіретті. Аллаһтан басқа құдай жоқ, Ол – жалғыз; Ол уәдесін орындады, құлына жәрдем берді және одақтас топтарды Өзі жалғыз жеңді». Содан кейін осылардың арасында дұға жасады. Мұндай сөзді үш рет айтты (хадистің соңына дейін). Сол хадисте: «Мәруада да Сафада істегенін істеді», – делінген."}, {"c": 119, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم: ((خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبيُّونَ مِنْ قَبْلِي: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).", "n": 1, "a": "237", "ru": "Пророк ﷺ сказал: «Лучшая мольба — мольба в день Арафа, и лучшее, что говорил я и пророки до меня: “Нет божества, кроме Аллаха, Единого, у Которого нет сотоварища; Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен”».", "kk": "Пайғамбар ﷺ айтты: «Ең жақсы дұға – Арафа күнгі дұға, ал мен және менен бұрынғы пайғамбарлар айтқан ең жақсы сөз: “Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ; билік Онікі, мадақ Оған тән және Ол – барлық нәрсеге құдіретті”»."}, {"c": 120, "ar": "رَكِبَ النَّبِيُّ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ، وَكَبَّرَهُ، وَهَللَّهُ، وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ.", "n": 1, "a": "238", "ru": "Пророк ﷺ сел на (верблюдицу) аль-Касва и доехал до аль-Маш‘ар аль-Харам, повернулся лицом к кибле (и обращался к Нему с мольбой, возвеличивал Его, произносил “нет божества, кроме Аллаха” и провозглашал Его единство) и продолжал стоять, пока совсем не рассвело, а затем двинулся в путь до восхода солнца.", "kk": "Пайғамбар ﷺ Қасуа (атты түйесіне) мініп, Мәшғарул-Харамға келді де, құбылаға бет бұрды (Оған дұға етті, Оны ұлықтады, “Аллаһтан басқа құдай жоқ” деп айтты және Оны бір деп таныды) және әбден жарық болғанша тұрды, содан кейін күн шықпай тұрып жолға шықты."}, {"c": 121, "ar": "((يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ، ثُمَّ يَتَقَدَّمُ، ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ، رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا)).", "n": 1, "a": "239", "ru": "«Он произносил такбир (“Аллах Велик”) всякий раз, бросая камешек у трёх джамаратов, затем проходил вперёд и стоял, обращаясь с мольбой, лицом к кибле, подняв руки, после первого и второго джамарата. Что же касается джамарат аль-‘Акаба, то он бросал в неё камешки, произнося такбир при каждом камешке, и уходил, не останавливаясь у неё».", "kk": "«Үш жәмрада әр тасты лақтырған сайын тәкбір айтатын (“Аллаһ ұлы” дейтін), содан кейін алға шығып, бірінші және екінші жәмрадан кейін құбылаға қарап, қолдарын көтеріп, дұға етіп тұратын. Ал Ақаба жәмрасына келсек, оған тас лақтырып, әр тас сайын тәкбір айтатын да, оның қасында тоқтамай кетіп қалатын»."}, {"c": 122, "ar": "((سُبْحَانَ اللَّهِ!)).", "n": 1, "a": "240", "ru": "«Пречист Аллах (Субханаллах)!»", "kk": "«Аллаһ пәк (Субханаллаһ)!»"}, {"c": 122, "ar": "((اللَّهُ أَكْبَرُ!)).", "n": 1, "a": "241", "ru": "«Аллах Велик (Аллаху акбар)!»", "kk": "«Аллаһ ұлы (Аллаһу әкбар)!»"}, {"c": 123, "ar": "((كَانَ النَّبيُّ صلى الله عليه وسلم إِذَا أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يُسَرُّ بِهِ خَرَّ سَاجِداً شُكْراً لِلَّهِ تَبَارَكَ وَتَعَالَى)).", "n": 1, "a": "242", "ru": "«Когда к Пророку ﷺ приходило что-то, что радовало его или чему он радовался, он падал ниц в земном поклоне, благодаря Аллаха, Благословенного и Всевышнего».", "kk": "«Пайғамбарға ﷺ өзін қуантатын немесе өзі қуанатын бір іс келсе, Аллаһқа (Ол берекелі әрі ұлы) шүкір етіп, сәждеге жығылатын»."}, {"c": 124, "ar": "((ضَعْ يَدَكَ عَلَى الَّذِي تَألَّمَ مِنْ جَسَدِكَ وَقُلْ: بِسْمِ اللَّهِ، ثَلاَثاً، وَقُلْ سَبْعَ مَرَّاتٍ: أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ)).", "n": 7, "a": "243", "ru": "«Положи руку на то место твоего тела, которое болит, и скажи: “С именем Аллаха (Бисмиллях)” — трижды, и скажи семь раз: “Прибегаю к Аллаху и Его могуществу от зла того, что я ощущаю и чего опасаюсь”».", "kk": "«Қолыңды денеңнің ауырған жеріне қойып, үш рет: “Аллаһтың атымен (Бисмиллаһ)”, – де де, жеті рет: “Сезіп отырған және қорқатын нәрсемнің жамандығынан Аллаһқа және Оның құдіретіне сиынамын”, – де»."}, {"c": 125, "ar": "((إِذَا رَأَى أَحَدُكُم مِنْ أَخِيهِ، أَوْ مِنْ نَفْسِهِ، أَوْ مِنْ مَالِهِ مَا يُعْجِبُهُ [فَلْيَدْعُ لَهُ بِالْبَرَكَةِ] فَإِنَّ الْعَيْنَ حَقٌّ)).", "n": 1, "a": "244", "ru": "«Если кто-либо из вас увидит в своём брате, или в себе самом, или в своём имуществе то, что ему понравится, [пусть попросит для этого благословения (баракат)], ибо сглаз — истина».", "kk": "«Егер біреулерің бауырынан, не өзінен, не мал-мүлкінен өзіне ұнаған нәрсені көрсе, [оған береке тілеп дұға етсін], өйткені көз тию – ақиқат»."}, {"c": 126, "ar": "((لاَ إِلَهَ إِلاَّ اللَّهُ!)).", "n": 1, "a": "245", "ru": "«Нет божества, кроме Аллаха!»", "kk": "«Аллаһтан басқа құдай жоқ!»"}, {"c": 127, "ar": "((بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اللَّهُمَّ مِنْكَ وَلَكَ] اللَّهُمَّ تَقَبَّلْ مِنِّي)).", "n": 1, "a": "246", "ru": "«С именем Аллаха, и Аллах Велик! [О Аллах, (это) от Тебя и для Тебя.] О Аллах, прими от меня».", "kk": "«Аллаһтың атымен, Аллаһ ұлы! [Уа, Аллаһ, (бұл) Сенен және Сен үшін.] Уа, Аллаһ, менен қабыл ет»."}, {"c": 128, "ar": "((أَعُوذُ بكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ)).", "n": 1, "a": "247", "ru": "«Прибегаю к совершенным словам Аллаха, которые не преступит ни благочестивый, ни нечестивый, от зла того, что Он сотворил, создал и рассеял, и от зла того, что нисходит с неба, и от зла того, что восходит на него, и от зла того, что Он рассеял на земле, и от зла того, что выходит из неё, и от зла искушений ночи и дня, и от зла всякого приходящего ночью, кроме приходящего с благом, о Милостивый!»", "kk": "«Аллаһтың кемел сөздеріне сиынамын, оларды ізгі адам да, күнәһар да аттап өте алмайды: Ол жаратқан, пайда еткен және таратқан нәрселердің жамандығынан, аспаннан түсетін нәрсенің жамандығынан, оған көтерілетін нәрсенің жамандығынан, Ол жерге таратқан нәрсенің жамандығынан, одан шығатын нәрсенің жамандығынан, түн мен күндіздің бүліктерінің жамандығынан және түнде келетін әрбір келушінің жамандығынан – тек игілікпен келетін келушіден басқа, уа, Рахман (Аса Мейірімді)!»"}, {"c": 129, "ar": "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ((وَاللَّهِ إِنِّي لأَسْتَغفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةٍ)).", "n": 1, "a": "248", "ru": "Посланник Аллаха ﷺ сказал: «Клянусь Аллахом, поистине, я прошу прощения у Аллаха и каюсь перед Ним более семидесяти раз в день».", "kk": "Аллаһтың елшісі ﷺ айтты: «Аллаһпен ант етемін, мен күніне жетпіс реттен көп Аллаһтан кешірім сұрап, Оған тәубе етемін»."}, {"c": 129, "ar": "وَقَالَ صلى الله عليه وسلم: ((يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ)).", "n": 100, "a": "249", "ru": "И он ﷺ сказал: «О люди, обращайтесь с покаянием к Аллаху, ибо я каюсь перед Ним сто раз в день».", "kk": "Ол ﷺ тағы айтты: «Әй, адамдар, Аллаһқа тәубе етіңдер, өйткені мен күніне жүз рет Оған тәубе етемін»."}, {"c": 129, "ar": "وَقَالَ صلى الله عليه وسلم: ((مَنْ قَالَ أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ القَيّوُمُ وَأَتُوبُ إِلَيهِ، غَفَرَ اللَّهُ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ)).", "n": 1, "a": "250", "ru": "И он ﷺ сказал: «Кто скажет: “Прошу прощения у Аллаха Великого, нет божества, кроме Него, Живого, Вседержителя, и каюсь перед Ним”, — того Аллах простит, даже если он бежал с поля боя».", "kk": "Ол ﷺ тағы айтты: «Кім: “Ұлы Аллаһтан кешірім сұраймын, Одан басқа құдай жоқ, Ол – Тірі, Мәңгі Тұрушы, әрі Оған тәубе етемін”, – десе, тіпті ұрыс майданынан қашқан болса да, Аллаһ оны кешіреді»."}, {"c": 129, "ar": "وَقَالَ صلى الله عليه وسلم: ((أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ)).", "n": 1, "a": "251", "ru": "И он ﷺ сказал: «Ближе всего Господь бывает к рабу в глубине последней части ночи; и если ты в силах быть из тех, кто поминает Аллаха в этот час, — будь».", "kk": "Ол ﷺ тағы айтты: «Раббы құлына ең жақын болатын кез – түннің соңғы бөлігінің ортасы; егер сол сағатта Аллаһты зікір ететіндердің қатарында болуға шамаң жетсе, бол»."}, {"c": 129, "ar": "وَقَالَ صلى الله عليه وسلم: ((أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكثِرُوا الدُّعَاءَ)).", "n": 1, "a": "252", "ru": "И он ﷺ сказал: «Ближе всего раб бывает к своему Господу, когда он совершает земной поклон, так умножайте же мольбы».", "kk": "Ол ﷺ тағы айтты: «Құл Раббысына ең жақын болатын кез – сәжде жасап жатқан кезі, сондықтан дұғаны көбейтіңдер»."}, {"c": 129, "ar": "وَقَالَ صلى الله عليه وسلم: ((إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ)).", "n": 100, "a": "253", "ru": "И он ﷺ сказал: «Поистине, моё сердце покрывает пелена, и, поистине, я прошу прощения у Аллаха сто раз в день».", "kk": "Ол ﷺ тағы айтты: «Шынында, жүрегімді бір бүркеу басады, және мен күніне жүз рет Аллаһтан кешірім сұраймын»."}, {"c": 130, "ar": "قَالَ صلى الله عليه وسلم مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْر)).", "n": 100, "a": "254", "ru": "Он ﷺ сказал: «Кто скажет: “Пречист Аллах и хвала Ему (Субханаллахи ва бихамдихи)” сто раз в день, с того будут сняты его прегрешения, даже если они подобны морской пене».", "kk": "Ол ﷺ айтты: «Кім бір күнде жүз рет: “Аллаһ пәк, әрі Оған мадақ (Субханаллаһи уә бихамдиһ)”, – десе, тіпті теңіз көбігіндей болса да, оның күнәлары түсіріледі»."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مِرَارٍ، كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ)).", "n": 10, "a": "255", "ru": "И он ﷺ сказал: «Кто скажет десять раз: “Нет божества, кроме Аллаха, Единого, у Которого нет сотоварища; Ему принадлежит власть, Ему хвала, и Он над всякой вещью мощен”, — тот будет подобен освободившему четырёх человек из потомков Исмаила».", "kk": "Ол ﷺ тағы айтты: «Кім он рет: “Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ; билік Онікі, мадақ Оған тән және Ол – барлық нәрсеге құдіретті”, – десе, Исмағыл ұрпағынан төрт адамды азат еткен кісідей болады»."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحانَ اللَّهِ الْعَظِيمِ)).", "n": 1, "a": "256", "ru": "И он ﷺ сказал: «Два слова, лёгкие для языка, тяжёлые на Весах, любимые Милостивым: “Пречист Аллах и хвала Ему, Пречист Аллах Великий” (Субханаллахи ва бихамдихи, Субханаллахиль-‘Азым)».", "kk": "Ол ﷺ тағы айтты: «Екі сөз бар – тілге жеңіл, Таразыда ауыр, Рахманға (Аса Мейірімдіге) сүйкімді: “Аллаһ пәк, әрі Оған мадақ, Ұлы Аллаһ пәк” (Субханаллаһи уә бихамдиһ, Субханаллаһил-Ағзым)»."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمسُ)).", "n": 1, "a": "257", "ru": "И он ﷺ сказал: «Сказать “Пречист Аллах, хвала Аллаху, нет божества, кроме Аллаха, и Аллах Велик” мне милее, чем всё, над чем восходит солнце».", "kk": "Ол ﷺ тағы айтты: «“Аллаһ пәк, Аллаһқа мадақ, Аллаһтан басқа құдай жоқ, Аллаһ ұлы” деп айтуым мен үшін күн шығатын барлық нәрседен де сүйіктірек»."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((أَيَعْجِزُ أَحَدُكُم أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ)) فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: ((يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ)).", "n": 100, "a": "258", "ru": "И он ﷺ сказал: «Разве не в силах кто-либо из вас приобретать каждый день тысячу добрых дел?» Один из сидевших с ним спросил: «Как же кто-то из нас может приобрести тысячу добрых дел?» Он сказал: «Пусть прославит (Аллаха) сто раз, и ему запишется тысяча добрых дел или с него будет снята тысяча прегрешений».", "kk": "Ол ﷺ тағы айтты: «Біреулерің күн сайын мың сауап табуға әлсіздік ете ме?» Сонда онымен бірге отырғандардың бірі: «Біреуміз мың сауапты қалай табады?» – деп сұрады. Ол: «Жүз рет тәсбих айтады (“Аллаһ пәк” дейді), сонда оған мың сауап жазылады немесе одан мың күнә түсіріледі», – деді."}, {"c": 130, "ar": "((مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ)).", "n": 1, "a": "259", "ru": "«Кто скажет: “Пречист Аллах Великий и хвала Ему (Субханаллахиль-‘Азыми ва бихамдихи)”, для того будет посажена финиковая пальма в Раю».", "kk": "«Кім: “Ұлы Аллаһ пәк, әрі Оған мадақ (Субханаллаһил-Ағзыми уә бихамдиһ)”, – десе, оған жәннатта бір құрма ағашы отырғызылады»."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ أَلاَ أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ))؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ((قُلْ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "n": 1, "a": "260", "ru": "И он ﷺ сказал: «О Абдуллах ибн Кайс, не указать ли тебе на одно из сокровищ Рая?» Я сказал: «Конечно, о Посланник Аллаха». Он сказал: «Говори: “Нет мощи и нет силы, кроме как у Аллаха (Ля хауля ва ля куввата илля билля)”».", "kk": "Ол ﷺ тағы айтты: «Әй, Абдуллаһ ибн Қайс, саған жәннат қазыналарының бір қазынасын көрсетейін бе?» Мен: «Әрине, уа, Аллаһтың елшісі», – дедім. Ол: «“Аллаһтан басқа ешбір күш те, қуат та жоқ (Лә хәулә уә лә қууәтә иллә билләһ)” де», – деді."}, {"c": 130, "ar": "وَقَالَ صلى الله عليه وسلم: ((أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأتَ)).", "n": 1, "a": "261", "ru": "И он ﷺ сказал: «Самые любимые Аллахом слова — четыре: “Пречист Аллах, хвала Аллаху, нет божества, кроме Аллаха, и Аллах Велик”. Тебе не повредит, с какого из них ты начнёшь».", "kk": "Ол ﷺ тағы айтты: «Аллаһқа ең сүйікті сөз төртеу: “Аллаһ пәк, Аллаһқа мадақ, Аллаһтан басқа құдай жоқ, Аллаһ ұлы”. Қайсысынан бастасаң да, саған зияны жоқ»."}, {"c": 130, "ar": "جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: ((قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ)) قَالَ: فَهَؤُلاَءِ لِرَبِّي، فَمَا لِي؟ قَالَ: ((قُلْ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي)).", "n": 1, "a": "262", "ru": "Один бедуин пришёл к Посланнику Аллаха ﷺ и сказал: «Научи меня словам, которые я буду говорить». Он сказал: «Говори: “Нет божества, кроме Аллаха, Единого, у Которого нет сотоварища; Аллах Велик величием великим, и Аллаху хвала обильная, Пречист Аллах, Господь миров, нет мощи и нет силы, кроме как у Аллаха, Могущественного, Мудрого”». Тот сказал: «Это — для моего Господа, а что же для меня?» Он сказал: «Говори: “О Аллах, прости меня, помилуй меня, наставь меня на прямой путь и надели меня уделом”».", "kk": "Бір бәдәуи Аллаһтың елшісіне ﷺ келіп: «Маған айтып жүретін сөз үйретші», – деді. Ол: «“Аллаһтан басқа құдай жоқ, Ол – жалғыз, Оның серігі жоқ; Аллаһ ұлы, шексіз ұлы, Аллаһқа көп-көп мадақ, әлемдердің Раббысы Аллаһ пәк, Аса Құдіретті, Аса Дана Аллаһтан басқа ешбір күш те, қуат та жоқ” де», – деді. Ол кісі: «Бұлар – Раббым үшін, ал маған не бар?» – деді. Ол: «“Уа, Аллаһ, мені кешір, маған рақым ет, мені тура жолға сал және маған ризық бер” де», – деді."}, {"c": 130, "ar": "كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ صلى الله عليه وسلم الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ: ((اللَّهُمَّ اغْفِرِ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي)).", "n": 1, "a": "263", "ru": "Когда человек принимал ислам, Пророк ﷺ обучал его молитве, а затем велел ему обращаться с мольбой такими словами: «О Аллах, прости меня, помилуй меня, наставь меня на прямой путь, даруй мне благополучие и надели меня уделом».", "kk": "Бір кісі мұсылман болғанда, Пайғамбар ﷺ оған намазды үйретіп, содан кейін мына сөздермен дұға етуді бұйыратын: «Уа, Аллаһ, мені кешір, маған рақым ет, мені тура жолға сал, маған саулық бер және маған ризық бер»."}, {"c": 130, "ar": "((إِنَّ أَفْضَلَ الدُّعَاءِ الْحَمْدُ لِلَّهِ، وَأَفْضَلَ الذِّكْرِ لاَ إِلَهَ إِلاَّ اللَّهُ)).", "n": 1, "a": "264", "ru": "«Поистине, лучшая мольба — “Хвала Аллаху”, а лучшее поминание — “Нет божества, кроме Аллаха”».", "kk": "«Шынында, ең абзал дұға – “Аллаһқа мадақ”, ал ең абзал зікір – “Аллаһтан басқа құдай жоқ”»."}, {"c": 130, "ar": "الباقيات الصالحات : سبحان الله والحمد لله ، ولا إله إلا الله ،والله أكبر ،و لا حول ولا قوة إلا بالله", "n": 1, "a": "265", "ru": "Непреходящие благие дела (аль-бакыят ас-салихат): «Пречист Аллах, хвала Аллаху, нет божества, кроме Аллаха, Аллах Велик, и нет мощи и нет силы, кроме как у Аллаха».", "kk": "Мәңгі қалатын ізгі амалдар (әл-бақият ас-салихат): «Аллаһ пәк, Аллаһқа мадақ, Аллаһтан басқа құдай жоқ, Аллаһ ұлы, Аллаһтан басқа ешбір күш те, қуат та жоқ»."}, {"c": 131, "ar": "عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رضي الله عنه قَالَ: ((رَأَيْتُ النَّبيَّ صلى الله عليه وسلم يَعْقِدُ التَّسْبِيحَ)) وفي زيادةٍ: ((بِيَمِينِهِ)).", "n": 1, "a": "266", "ru": "Передаётся, что Абдуллах ибн Амр (да будет доволен им Аллах) сказал: «Я видел, как Пророк ﷺ отсчитывал тасбих (на пальцах)», а в дополнении (сказано): «правой рукой».", "kk": "Абдуллаһ ибн Амрдан (Аллаһ оған разы болсын) жеткен: «Пайғамбардың ﷺ тәсбихті (саусақтарымен) санағанын көрдім». Бір қосымша риуаятта: «оң қолымен», – делінген."}, {"c": 132, "ar": "قَالَ النَّبِيُّ صلى الله عليه وسلم ((إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَـكُفُّوا صِبْيانَـكُم، فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً، وَأَوْكُوا قِرَبَكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُم، وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً، وَأَطْفِئُوا مَصَابِيحَكُمْ)).", "n": 1, "a": "267", "ru": "Пророк ﷺ сказал: «Когда наступит ночная тьма — или: когда наступит вечер, — удерживайте своих детей (дома), ибо в это время шайтаны рассеиваются. Когда же пройдёт час ночи, отпустите их. Запирайте двери и поминайте имя Аллаха, ибо шайтан не открывает запертую дверь; завязывайте свои бурдюки и поминайте имя Аллаха; накрывайте свою посуду и поминайте имя Аллаха, хотя бы положив на неё что-нибудь поперёк; и гасите свои светильники».", "kk": "Пайғамбар ﷺ айтты: «Түн қараңғылығы түскенде – немесе кеш батқанда – балаларыңды (сыртқа шығармай) ұстаңдар, өйткені сол кезде шайтандар тарайды. Түннің бір сағаты өткенде, оларды жіберіңдер. Есіктерді жауып, Аллаһтың атын еске алыңдар, өйткені шайтан жабық есікті ашпайды; мес-торсықтарыңның аузын байлап, Аллаһтың атын еске алыңдар; ыдыстарыңды жауып, Аллаһтың атын еске алыңдар, тіпті үстіне көлденең бір нәрсе қойып болса да; және шырағдандарыңды сөндіріңдер»."}];
